/// Bounded activation payload captured from a brain for inspection.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct BrainActivations {
    /// Activation layers in evaluation order.
    pub layers: Vec<ActivationLayer>,
    /// Weighted edges between layers.
    #[serde(default)]
    pub connections: Vec<ActivationEdge>,
    /// Set when the snapshot was clipped to fit [`ACTIVATION_VALUE_BUDGET`].
    ///
    /// An inspector showing a truncated view must say so. Silently dropping
    /// layers would let a user conclude a brain has no deep structure when in
    /// fact we simply refused to copy it.
    #[serde(default)]
    pub truncated: bool,
}

/// One named activation layer within a [`BrainActivations`] capture.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ActivationLayer {
    /// Layer display name.
    pub name: String,
    /// Layer grid width.
    pub width: usize,
    /// Layer grid height.
    pub height: usize,
    /// Row-major activation values (width*height).
    pub values: Vec<f32>,
}

/// One weighted connection between two neurons in a [`BrainActivations`] capture.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
pub struct ActivationEdge {
    /// Source neuron index.
    pub from: usize,
    /// Target neuron index.
    pub to: usize,
    /// Signed edge weight.
    pub weight: f32,
}

#[cfg(all(feature = "parallel", not(target_arch = "wasm32")))]
static RAYON_LIMIT_GUARD: OnceLock<()> = OnceLock::new();

#[cfg(feature = "parallel")]
fn par_min_split() -> usize {
    use std::sync::OnceLock;
    static PAR_MIN_SPLIT: OnceLock<usize> = OnceLock::new();
    *PAR_MIN_SPLIT.get_or_init(|| {
        std::env::var("SCRIPTBOTS_PAR_MIN_SPLIT")
            .ok()
            .and_then(|raw| raw.trim().parse::<usize>().ok())
            .filter(|&v| v > 0)
            .unwrap_or(1024)
    })
}

#[cfg(feature = "parallel")]
macro_rules! collect_handles {
    ($handles:expr, |$idx:ident, $handle:pat_param| $body:expr) => {{
        ($handles)
            .par_iter()
            .with_min_len(par_min_split())
            .enumerate()
            .map(|($idx, $handle)| $body)
            .collect::<Vec<_>>()
    }};
}

#[cfg(not(feature = "parallel"))]
macro_rules! collect_handles {
    ($handles:expr, |$idx:ident, $handle:pat_param| $body:expr) => {{
        ($handles)
            .iter()
            .enumerate()
            .map(|($idx, $handle)| $body)
            .collect::<Vec<_>>()
    }};
}

new_key_type! {
    /// Stable handle for agents backed by a generational slot map.
    pub struct AgentId;
}

impl AgentId {
    /// Stable raw key representation used by external control DTOs.
    #[must_use]
    pub fn raw(self) -> u64 {
        self.data().as_ffi()
    }
}

/// Stable logical identity for an agent within one simulation run.
///
/// Unlike [`AgentId`], this value is never recycled when a `SlotMap` entry is removed. Scientific
/// snapshots, lineage, replay, and persistence use this identity; the generational handle remains
/// the efficient in-memory lookup key.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct AgentUid(
    /// Raw stable identity value, never reused within a run.
    pub u64,
);

impl AgentUid {
    /// Return the integer representation used by persistence and protocol DTOs.
    #[must_use]
    pub const fn get(self) -> u64 {
        self.0
    }
}

/// Stable creation-order metadata attached to one live agent.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
pub struct AgentIdentity {
    /// Stable logical identity of the agent.
    pub uid: AgentUid,
    /// Monotonic ordinal assigned to every successful insertion, including injected agents.
    pub spawn_ordinal: u64,
    /// Monotonic ordinal assigned only to offspring produced from parent agents.
    pub birth_ordinal: Option<u64>,
}

/// Stable manifest/checkpoint projection of one live agent's keyed-RNG continuation.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AgentRngCounterStateV1 {
    agent_uid: AgentUid,
    counters: AgentRngCountersV1,
}

impl AgentRngCounterStateV1 {
    /// Construct one UID-keyed continuation row.
    #[must_use]
    pub const fn new(agent_uid: AgentUid, counters: AgentRngCountersV1) -> Self {
        Self {
            agent_uid,
            counters,
        }
    }

    /// Stable logical identity owning these counters.
    #[must_use]
    pub const fn agent_uid(self) -> AgentUid {
        self.agent_uid
    }

    /// Exact next-unused ordinals for the agent-keyed protocol.
    #[must_use]
    pub const fn counters(self) -> AgentRngCountersV1 {
        self.counters
    }
}

/// Version of the restorable adapter state carried by [`RandomStreamState`].
pub const RANDOM_STREAM_STATE_VERSION: u16 = 1;
/// Maximum opaque state payload accepted from any random-stream implementation.
pub const MAX_RANDOM_STREAM_STATE_BYTES: usize = 256;
const SMALL_RNG_STATE_CODEC_VERSION: u16 = 1;
const SMALL_RNG_STATE_BYTES: usize = 8 + 4 * 8;

#[cfg(target_pointer_width = "64")]
const RANDOM_STREAM_ALGORITHM: &str = "rand-0.9.5-smallrng-xoshiro256plusplus-64-seed-from-u64";
#[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
const RANDOM_STREAM_ALGORITHM: &str = "rand-0.9.5-smallrng-xoshiro128plusplus-32-seed-from-u64";

/// Serializable continuation state for one random-stream adapter.
///
/// `SmallRng` deliberately does not promise a portable, serializable state. This first protocol
/// therefore carries a bounded opaque payload identified by an algorithm and codec version. The
/// current adapter's private codec records its seed and four state words as explicit little-endian
/// `u64`s. Restore is constant-time and validates versions and lengths before decoding, so
/// untrusted state cannot request unbounded work. This preserves the existing generator and
/// fixed-seed behavior without constraining future adapters to xoshiro's state shape, selecting a
/// replacement generator, or claiming domain separation.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct RandomStreamState {
    /// Envelope version (`RANDOM_STREAM_STATE_VERSION`).
    pub version: u16,
    /// Stable algorithm identifier.
    pub algorithm: String,
    /// Payload codec revision.
    pub codec_version: u16,
    /// Bounded opaque continuation payload.
    #[serde(deserialize_with = "deserialize_bounded_random_stream_state")]
    pub state: Vec<u8>,
}

fn deserialize_bounded_random_stream_state<'de, D>(deserializer: D) -> Result<Vec<u8>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    struct BoundedStateVisitor;

    impl<'de> serde::de::Visitor<'de> for BoundedStateVisitor {
        type Value = Vec<u8>;

        fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(
                formatter,
                "at most {MAX_RANDOM_STREAM_STATE_BYTES} random-stream state bytes"
            )
        }

        fn visit_seq<A>(self, mut sequence: A) -> Result<Self::Value, A::Error>
        where
            A: serde::de::SeqAccess<'de>,
        {
            let hinted = sequence.size_hint().unwrap_or_default();
            if hinted > MAX_RANDOM_STREAM_STATE_BYTES {
                return Err(serde::de::Error::invalid_length(hinted, &self));
            }
            let mut state = Vec::with_capacity(hinted);
            while let Some(byte) = sequence.next_element()? {
                if state.len() == MAX_RANDOM_STREAM_STATE_BYTES {
                    return Err(serde::de::Error::invalid_length(state.len() + 1, &self));
                }
                state.push(byte);
            }
            Ok(state)
        }
    }

    deserializer.deserialize_seq(BoundedStateVisitor)
}

/// Failure to restore a random stream state produced by another protocol or algorithm lane.
#[derive(Debug, Clone, Error, PartialEq, Eq)]
pub enum RandomStreamRestoreError {
    /// State envelope version did not match the expected protocol version.
    #[error("unsupported random-stream state version {found}; expected {expected}")]
    UnsupportedVersion {
        /// Version found in the decoded state.
        found: u16,
        /// Version this build expects.
        expected: u16,
    },
    /// Algorithm identifier did not match this adapter's stable identifier.
    #[error("unsupported random-stream algorithm `{found}`; expected `{expected}`")]
    UnsupportedAlgorithm {
        /// Algorithm identifier found in the decoded state.
        found: String,
        /// Algorithm identifier this adapter expects.
        expected: &'static str,
    },
    /// Payload codec revision did not match the expected revision.
    #[error("unsupported random-stream codec version {found}; expected {expected}")]
    UnsupportedCodecVersion {
        /// Codec revision found in the decoded state.
        found: u16,
        /// Codec revision this build expects.
        expected: u16,
    },
    /// State payload exceeded the bounded-size contract.
    #[error("random-stream state payload is {found} bytes; maximum is {maximum}")]
    StateTooLarge {
        /// Payload size found in the decoded state.
        found: usize,
        /// Maximum permitted payload size.
        maximum: usize,
    },
    /// State payload length did not match the algorithm's exact state width.
    #[error("invalid random-stream state length {found}; expected exactly {expected} bytes")]
    InvalidStateLength {
        /// Payload length found in the decoded state.
        found: usize,
        /// Exact payload length the algorithm requires.
        expected: usize,
    },
    /// All-zero state would collapse the generator into a degenerate orbit.
    #[error("invalid all-zero random-stream state")]
    AllZeroState,
    /// State word exceeded the 32-bit algorithm width.
    #[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
    #[error("random-stream state word {index} exceeds the 32-bit algorithm width: {value}")]
    StateWordOutOfRange {
        /// Index of the offending state word.
        index: usize,
        /// Offending word value.
        value: u64,
    },
}

/// Object-safe random-stream protocol consumed by core and brain families.
///
/// Each world random domain owns a [`SmallRngStream`], while consumers depend only on this
/// checkpointable interface. Domain selection lives one layer above this generator protocol.
pub trait RandomStream: RngCore {
    /// Stable identity of the concrete algorithm/state encoding.
    fn algorithm_id(&self) -> &'static str;

    /// Capture a versioned, serializable continuation state.
    fn checkpoint(&self) -> RandomStreamState;
}

/// Restorable adapter around the world's existing [`SmallRng`] algorithm.
///
/// The adapter implements [`RngCore`], so core and brain-family consumers retain the exact
/// sampling operations they need after selecting an explicit world domain.
#[derive(Clone, Debug)]
pub struct SmallRngStream {
    seed: u64,
    state_words: [u64; 4],
}

impl SmallRngStream {
    /// Construct the current adapter with the same `SmallRng::seed_from_u64` behavior used before
    /// this protocol existed.
    #[must_use]
    pub fn seed_from_u64(seed: u64) -> Self {
        let mut splitmix_state = seed;
        #[cfg(target_pointer_width = "64")]
        let state_words = std::array::from_fn(|_| splitmix64(&mut splitmix_state));
        #[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
        let state_words = {
            let first = splitmix64(&mut splitmix_state);
            let second = splitmix64(&mut splitmix_state);
            [
                first & u64::from(u32::MAX),
                first >> 32,
                second & u64::from(u32::MAX),
                second >> 32,
            ]
        };
        debug_assert!(state_words.iter().any(|word| *word != 0));
        Self { seed, state_words }
    }

    /// Stable identity of the current adapted algorithm lane.
    #[must_use]
    pub const fn algorithm() -> &'static str {
        RANDOM_STREAM_ALGORITHM
    }

    /// Return the construction seed embedded in this stream's continuation state.
    #[must_use]
    pub const fn seed(&self) -> u64 {
        self.seed
    }

    /// Capture a serializable continuation state.
    #[must_use]
    fn state(&self) -> RandomStreamState {
        let mut state = Vec::with_capacity(SMALL_RNG_STATE_BYTES);
        state.extend_from_slice(&self.seed.to_le_bytes());
        for word in self.state_words {
            state.extend_from_slice(&word.to_le_bytes());
        }
        RandomStreamState {
            version: RANDOM_STREAM_STATE_VERSION,
            algorithm: RANDOM_STREAM_ALGORITHM.to_owned(),
            codec_version: SMALL_RNG_STATE_CODEC_VERSION,
            state,
        }
    }

    /// Restore the exact continuation represented by `state` in constant time.
    ///
    /// Version, algorithm, word width, and the xoshiro all-zero forbidden state are validated
    /// before construction. An error performs no sampling and has no externally visible state.
    pub fn from_state(state: &RandomStreamState) -> Result<Self, RandomStreamRestoreError> {
        if state.version != RANDOM_STREAM_STATE_VERSION {
            return Err(RandomStreamRestoreError::UnsupportedVersion {
                found: state.version,
                expected: RANDOM_STREAM_STATE_VERSION,
            });
        }
        if state.algorithm != RANDOM_STREAM_ALGORITHM {
            return Err(RandomStreamRestoreError::UnsupportedAlgorithm {
                found: state.algorithm.clone(),
                expected: RANDOM_STREAM_ALGORITHM,
            });
        }
        if state.codec_version != SMALL_RNG_STATE_CODEC_VERSION {
            return Err(RandomStreamRestoreError::UnsupportedCodecVersion {
                found: state.codec_version,
                expected: SMALL_RNG_STATE_CODEC_VERSION,
            });
        }
        if state.state.len() > MAX_RANDOM_STREAM_STATE_BYTES {
            return Err(RandomStreamRestoreError::StateTooLarge {
                found: state.state.len(),
                maximum: MAX_RANDOM_STREAM_STATE_BYTES,
            });
        }
        if state.state.len() != SMALL_RNG_STATE_BYTES {
            return Err(RandomStreamRestoreError::InvalidStateLength {
                found: state.state.len(),
                expected: SMALL_RNG_STATE_BYTES,
            });
        }

        let seed = decode_le_u64(&state.state[0..8]);
        let state_words = std::array::from_fn(|index| {
            let start = 8 + index * 8;
            decode_le_u64(&state.state[start..start + 8])
        });
        if state_words.iter().all(|word| *word == 0) {
            return Err(RandomStreamRestoreError::AllZeroState);
        }
        #[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
        for (index, value) in state_words.iter().copied().enumerate() {
            if value > u64::from(u32::MAX) {
                return Err(RandomStreamRestoreError::StateWordOutOfRange { index, value });
            }
        }
        Ok(Self { seed, state_words })
    }
}

#[inline]
const fn decode_le_u64(bytes: &[u8]) -> u64 {
    u64::from_le_bytes([
        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
    ])
}

#[inline]
const fn splitmix64(state: &mut u64) -> u64 {
    const PHI: u64 = 0x9e37_79b9_7f4a_7c15;
    *state = state.wrapping_add(PHI);
    let mut value = *state;
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

impl RngCore for SmallRngStream {
    #[inline]
    fn next_u32(&mut self) -> u32 {
        #[cfg(target_pointer_width = "64")]
        {
            (self.next_u64() >> 32) as u32
        }
        #[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
        {
            let mut words = self.state_words.map(|word| word as u32);
            let result = words[0]
                .wrapping_add(words[3])
                .rotate_left(7)
                .wrapping_add(words[0]);
            let shifted = words[1] << 9;
            words[2] ^= words[0];
            words[3] ^= words[1];
            words[1] ^= words[2];
            words[0] ^= words[3];
            words[2] ^= shifted;
            words[3] = words[3].rotate_left(11);
            self.state_words = words.map(u64::from);
            result
        }
    }

    #[inline]
    fn next_u64(&mut self) -> u64 {
        #[cfg(target_pointer_width = "64")]
        {
            let result = self.state_words[0]
                .wrapping_add(self.state_words[3])
                .rotate_left(23)
                .wrapping_add(self.state_words[0]);
            let shifted = self.state_words[1] << 17;
            self.state_words[2] ^= self.state_words[0];
            self.state_words[3] ^= self.state_words[1];
            self.state_words[1] ^= self.state_words[2];
            self.state_words[0] ^= self.state_words[3];
            self.state_words[2] ^= shifted;
            self.state_words[3] = self.state_words[3].rotate_left(45);
            result
        }
        #[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
        {
            let low = u64::from(self.next_u32());
            let high = u64::from(self.next_u32());
            (high << 32) | low
        }
    }

    #[inline]
    fn fill_bytes(&mut self, destination: &mut [u8]) {
        #[cfg(target_pointer_width = "64")]
        {
            let (chunks, remainder) = destination.as_chunks_mut::<8>();
            for chunk in chunks {
                *chunk = self.next_u64().to_le_bytes();
            }
            if remainder.len() > 4 {
                let bytes = self.next_u64().to_le_bytes();
                remainder.copy_from_slice(&bytes[..remainder.len()]);
            } else if !remainder.is_empty() {
                let bytes = self.next_u32().to_le_bytes();
                remainder.copy_from_slice(&bytes[..remainder.len()]);
            }
        }
        #[cfg(any(target_pointer_width = "16", target_pointer_width = "32"))]
        {
            let (chunks, remainder) = destination.as_chunks_mut::<4>();
            for chunk in chunks {
                *chunk = self.next_u32().to_le_bytes();
            }
            if !remainder.is_empty() {
                let bytes = self.next_u32().to_le_bytes();
                remainder.copy_from_slice(&bytes[..remainder.len()]);
            }
        }
    }
}

impl RandomStream for SmallRngStream {
    fn algorithm_id(&self) -> &'static str {
        Self::algorithm()
    }

    fn checkpoint(&self) -> RandomStreamState {
        self.state()
    }
}

/// Convenience alias for associating side data with agents.
pub type AgentMap<T> = SecondaryMap<AgentId, T>;

/// Number of sensor inputs wired into each agent brain.
pub const INPUT_SIZE: usize = 25;
/// Number of control outputs produced by each agent brain.
pub const OUTPUT_SIZE: usize = 9;
/// Number of directional eyes each agent possesses.
pub const NUM_EYES: usize = 4;

/// Maximum stable agent identities admitted by one explicit brain-inspection request.
///
/// Selection and hover state never authorize inspection. A caller that needs more
/// targets must issue another bounded request rather than silently sampling a subset.
pub const ACTIVATION_CAPTURE_BUDGET: usize = 8;

/// Maximum activation layers retained by one inspected brain.
pub const ACTIVATION_LAYER_BUDGET: usize = 64;

/// Maximum UTF-8 bytes retained across activation-layer names.
pub const ACTIVATION_NAME_BYTE_BUDGET: usize = 1_024;

/// Maximum number of activation values copied out of a single brain per request.
///
/// Bounding *how many* agents are captured is not enough: one agent's snapshot
/// must also be bounded in size. Brain topology is configuration (a Neuroflow
/// net can be declared with arbitrarily wide hidden layers), so without a cap a
/// single inspected agent could copy megabytes out of the simulation every tick.
/// Snapshots past this budget are clipped and marked
/// [`BrainActivations::truncated`] — never silently shortened.
pub const ACTIVATION_VALUE_BUDGET: usize = 4_096;

/// Maximum activation edges retained by one inspected brain.
pub const ACTIVATION_EDGE_BUDGET: usize = 1_024;

/// Maximum retained in-memory bytes for one activation payload.
pub const ACTIVATION_PAYLOAD_BYTE_BUDGET: usize = 64 * 1_024;

/// Maximum family-owned scalar work admitted before an activation payload is built.
///
/// `NeuroFlow` uses this preflight before serializing its private network representation.
pub const ACTIVATION_SOURCE_SCALAR_BUDGET: usize = 65_536;

/// Producer-side limits carried by every explicit brain-inspection request.
// bd-tqpj: shared `max_` prefix mirrors the wire-format budget family; renaming
// fields would churn the serialization layout, so the field-names lint is waived.
#[allow(clippy::struct_field_names)]
#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
pub struct BrainInspectionLimits {
    max_layers: usize,
    max_name_bytes: usize,
    max_values: usize,
    max_edges: usize,
    max_payload_bytes: usize,
    max_source_scalars: usize,
}

// bd-tqpj: wire mirror of `BrainInspectionLimits`; the shared `max_` prefix is the
// serialization contract, so the field-names lint is waived.
#[allow(clippy::struct_field_names)]
#[derive(Deserialize)]
struct BrainInspectionLimitsWire {
    max_layers: usize,
    max_name_bytes: usize,
    max_values: usize,
    max_edges: usize,
    max_payload_bytes: usize,
    max_source_scalars: usize,
}

impl<'de> Deserialize<'de> for BrainInspectionLimits {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = BrainInspectionLimitsWire::deserialize(deserializer)?;
        Ok(Self::tightened(
            wire.max_layers,
            wire.max_name_bytes,
            wire.max_values,
            wire.max_edges,
            wire.max_payload_bytes,
            wire.max_source_scalars,
        ))
    }
}

impl BrainInspectionLimits {
    /// The project-wide hard ceiling. Callers may tighten but never expand it.
    #[must_use]
    pub const fn hard() -> Self {
        Self {
            max_layers: ACTIVATION_LAYER_BUDGET,
            max_name_bytes: ACTIVATION_NAME_BYTE_BUDGET,
            max_values: ACTIVATION_VALUE_BUDGET,
            max_edges: ACTIVATION_EDGE_BUDGET,
            max_payload_bytes: ACTIVATION_PAYLOAD_BYTE_BUDGET,
            max_source_scalars: ACTIVATION_SOURCE_SCALAR_BUDGET,
        }
    }

    /// Construct a request no larger than the hard ceiling on every axis.
    #[must_use]
    pub fn tightened(
        max_layers: usize,
        max_name_bytes: usize,
        max_values: usize,
        max_edges: usize,
        max_payload_bytes: usize,
        max_source_scalars: usize,
    ) -> Self {
        Self {
            max_layers: max_layers.min(ACTIVATION_LAYER_BUDGET),
            max_name_bytes: max_name_bytes.min(ACTIVATION_NAME_BYTE_BUDGET),
            max_values: max_values.min(ACTIVATION_VALUE_BUDGET),
            max_edges: max_edges.min(ACTIVATION_EDGE_BUDGET),
            max_payload_bytes: max_payload_bytes.min(ACTIVATION_PAYLOAD_BYTE_BUDGET),
            max_source_scalars: max_source_scalars.min(ACTIVATION_SOURCE_SCALAR_BUDGET),
        }
    }

    /// Request ceiling for the maximum number of retained layers.
    #[must_use]
    pub const fn max_layers(self) -> usize {
        self.max_layers
    }

    /// Request ceiling for the maximum retained layer-name bytes.
    #[must_use]
    pub const fn max_name_bytes(self) -> usize {
        self.max_name_bytes
    }

    /// Request ceiling for the maximum retained activation values.
    #[must_use]
    pub const fn max_values(self) -> usize {
        self.max_values
    }

    /// Request ceiling for the maximum retained activation edges.
    #[must_use]
    pub const fn max_edges(self) -> usize {
        self.max_edges
    }

    /// Request ceiling for the maximum retained payload bytes.
    #[must_use]
    pub const fn max_payload_bytes(self) -> usize {
        self.max_payload_bytes
    }

    /// Request ceiling for the maximum family-owned source scalars.
    #[must_use]
    pub const fn max_source_scalars(self) -> usize {
        self.max_source_scalars
    }
}

impl Default for BrainInspectionLimits {
    fn default() -> Self {
        Self::hard()
    }
}

/// Structural work and retained-memory evidence for one activation inspection.
#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct BrainInspectionBuildStats {
    /// Producer-side pre-bound scalar count.
    pub source_scalars: usize,
    /// Producer-side pre-bound layer count.
    pub source_layers: usize,
    /// Producer-side pre-bound layer-name bytes.
    pub source_name_bytes: usize,
    /// Producer-side pre-bound activation value count.
    pub source_values: usize,
    /// Producer-side pre-bound activation edge count.
    pub source_edges: usize,
    /// Post-bound retained layer count.
    pub retained_layers: usize,
    /// Post-bound retained layer-name bytes.
    pub retained_name_bytes: usize,
    /// Post-bound retained activation value count.
    pub retained_values: usize,
    /// Post-bound retained activation edge count.
    pub retained_edges: usize,
    /// Post-bound retained payload bytes.
    pub retained_payload_bytes: usize,
    /// Whether any budget clipped the payload.
    pub truncated: bool,
}

/// A family-produced activation payload after all request-time bounds are applied.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct BrainInspectionSnapshot {
    /// Bounded activation payload.
    pub activations: BrainActivations,
    /// Structural cost evidence for the build.
    pub build: BrainInspectionBuildStats,
}

/// Typed refusal at the read-only brain-inspection boundary.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Error)]
pub enum BrainInspectionError {
    /// Request exceeded the hard target-count bound.
    #[error("brain inspection requested {requested} targets, exceeding hard limit {limit}")]
    TargetLimitExceeded {
        /// Number of targets requested.
        requested: usize,
        /// Hard target-count limit.
        limit: usize,
    },
    /// Family required more source scalars than the request admitted.
    #[error(
        "brain family `{family}` requires {required} source scalars for inspection, exceeding request limit {limit}"
    )]
    SourceScalarLimitExceeded {
        /// Brain family that produced the refusal.
        family: String,
        /// Source scalars the family requires.
        required: usize,
        /// Request scalar limit.
        limit: usize,
    },
    /// Family produced invalid inspection data.
    #[error("brain family `{family}` produced invalid inspection data: {detail}")]
    InvalidPayload {
        /// Brain family that produced the payload.
        family: String,
        /// Description of the invalid data.
        detail: String,
    },
}

fn activation_payload_bytes(activations: &BrainActivations) -> usize {
    activation_payload_bytes_parts(
        &activations.layers,
        activations.layers.capacity(),
        activations.connections.capacity(),
    )
}

fn activation_payload_bytes_parts(
    layers: &[ActivationLayer],
    layer_capacity: usize,
    connection_capacity: usize,
) -> usize {
    layer_capacity
        .saturating_mul(std::mem::size_of::<ActivationLayer>())
        .saturating_add(
            layers
                .iter()
                .map(|layer| {
                    layer.name.capacity().saturating_add(
                        layer
                            .values
                            .capacity()
                            .saturating_mul(std::mem::size_of::<f32>()),
                    )
                })
                .fold(0usize, usize::saturating_add),
        )
        .saturating_add(connection_capacity.saturating_mul(std::mem::size_of::<ActivationEdge>()))
}

/// Apply the complete structural and retained-byte contract to a family payload.
///
/// Families call this while constructing their response; the world calls it again as
/// defense in depth. Output capacities are rebuilt from bounded lengths so an untrusted
/// producer cannot retain a tiny vector backed by an enormous allocation.
// bd-tqpj: mirrors legacy C++ parity layout; reviewed as a unit.
#[allow(clippy::too_many_lines)]
pub fn bound_brain_inspection(
    family: &str,
    activations: BrainActivations,
    source_scalars: usize,
    limits: BrainInspectionLimits,
) -> Result<BrainInspectionSnapshot, BrainInspectionError> {
    if source_scalars > limits.max_source_scalars {
        return Err(BrainInspectionError::SourceScalarLimitExceeded {
            family: family.to_owned(),
            required: source_scalars,
            limit: limits.max_source_scalars,
        });
    }

    let source_layers = activations.layers.len();
    let source_name_bytes = activations
        .layers
        .iter()
        .map(|layer| layer.name.len())
        .fold(0usize, usize::saturating_add);
    let source_values = activations
        .layers
        .iter()
        .map(|layer| layer.values.len())
        .fold(0usize, usize::saturating_add);
    let source_edges = activations.connections.len();
    let mut truncated = activations.truncated;
    let mut retained_name_bytes = 0usize;
    let mut retained_values = 0usize;
    let layer_capacity = source_layers.min(limits.max_layers);
    let mut layers = Vec::with_capacity(layer_capacity);

    for layer in activations.layers {
        if layers.len() == limits.max_layers {
            truncated = true;
            break;
        }
        let Some(cell_count) = layer.width.checked_mul(layer.height) else {
            truncated = true;
            break;
        };
        if cell_count < layer.values.len()
            || cell_count > ACTIVATION_VALUE_BUDGET
            || layer.values.iter().any(|value| !value.is_finite())
            || retained_name_bytes.saturating_add(layer.name.len()) > limits.max_name_bytes
            || retained_values.saturating_add(layer.values.len()) > limits.max_values
        {
            truncated = true;
            break;
        }

        let name = layer.name.into_boxed_str().into_string();
        let values = layer.values.into_boxed_slice().into_vec();
        let candidate = ActivationLayer {
            name,
            width: layer.width,
            height: layer.height,
            values,
        };
        retained_name_bytes = retained_name_bytes.saturating_add(candidate.name.len());
        retained_values = retained_values.saturating_add(candidate.values.len());
        layers.push(candidate);

        if activation_payload_bytes_parts(&layers, layers.len(), 0) > limits.max_payload_bytes {
            let _removed = layers.pop();
            truncated = true;
            break;
        }
    }

    let mut connections = Vec::new();
    if !truncated {
        let max_cells = layers
            .iter()
            .filter_map(|layer| layer.width.checked_mul(layer.height))
            .max()
            .unwrap_or_default();
        connections = Vec::with_capacity(source_edges.min(limits.max_edges));
        for edge in activations.connections {
            if connections.len() == limits.max_edges
                || !edge.weight.is_finite()
                || edge.from >= max_cells
                || edge.to >= max_cells
            {
                truncated = true;
                break;
            }
            connections.push(edge);
            if activation_payload_bytes_parts(&layers, layers.len(), connections.len())
                > limits.max_payload_bytes
            {
                connections.pop();
                truncated = true;
                break;
            }
        }
    }

    let mut activations = BrainActivations {
        layers: layers.into_boxed_slice().into_vec(),
        connections: connections.into_boxed_slice().into_vec(),
        truncated,
    };
    let retained_payload_bytes = activation_payload_bytes(&activations);
    if retained_payload_bytes > limits.max_payload_bytes {
        activations.layers = Vec::new();
        activations.connections = Vec::new();
        activations.truncated = true;
    }
    let retained_payload_bytes = activation_payload_bytes(&activations);
    Ok(BrainInspectionSnapshot {
        build: BrainInspectionBuildStats {
            source_scalars,
            source_layers,
            source_name_bytes,
            source_values,
            source_edges,
            retained_layers: activations.layers.len(),
            retained_name_bytes: activations
                .layers
                .iter()
                .map(|layer| layer.name.len())
                .sum(),
            retained_values: activations
                .layers
                .iter()
                .map(|layer| layer.values.len())
                .sum(),
            retained_edges: activations.connections.len(),
            retained_payload_bytes,
            truncated: activations.truncated,
        },
        activations,
    })
}

const FULL_TURN: f32 = std::f32::consts::TAU;
const HALF_TURN: f32 = std::f32::consts::PI;
// Legacy-parity policy: World.cpp defines PI8 = π/16 and PI38 = 3 * PI8, then admits blood
// targets only for `diff4 < PI38`. Commit e2d9aaa already corrected the former accidental 3π/8
// cone on this baseline; the shared contribution function below proves its strict boundary.
const BLOOD_HALF_FOV: f32 = std::f32::consts::PI * 0.1875;

// bd-tqpj: while-on-float mirrors the legacy C++ wrap loop; a modulo rewrite would change
// evaluation order for large angles and shift world digests.
#[allow(clippy::while_float)]
fn wrap_signed_angle(mut angle: f32) -> f32 {
    if angle.is_nan() {
        return 0.0;
    }
    while angle <= -HALF_TURN {
        angle += FULL_TURN;
    }
    while angle > HALF_TURN {
        angle -= FULL_TURN;
    }
    angle
}

// bd-tqpj: while-on-float mirrors the legacy C++ wrap loop; a modulo rewrite would change
// evaluation order for large angles and shift world digests.
#[allow(clippy::while_float)]
fn wrap_unsigned_angle(mut angle: f32) -> f32 {
    if angle.is_nan() {
        return 0.0;
    }
    while angle < 0.0 {
        angle += FULL_TURN;
    }
    while angle >= FULL_TURN {
        angle -= FULL_TURN;
    }
    angle
}

#[cfg(all(feature = "parallel", not(target_arch = "wasm32")))]
fn configure_parallelism() {
    use std::cmp::max;

    RAYON_LIMIT_GUARD.get_or_init(|| {
        if std::env::var("RAYON_NUM_THREADS").is_ok() {
            return;
        }

        let cpu_count = max(1, num_cpus::get_physical());
        let env_limit = std::env::var("SCRIPTBOTS_MAX_THREADS")
            .ok()
            .and_then(|raw| raw.trim().parse::<usize>().ok())
            .filter(|value| *value > 0);

        let mut limit = env_limit.unwrap_or_else(|| default_thread_budget(cpu_count));
        if limit > cpu_count {
            limit = cpu_count;
        }
        if limit == 0 {
            limit = 1;
        }

        // SAFETY: `limit` is a finite positive integer converted to string; the standard library
        // marks `set_var` as unsafe on nightly, but providing well-formed Unicode strings is safe.
        #[allow(unsafe_code)]
        unsafe {
            std::env::set_var("RAYON_NUM_THREADS", limit.to_string());
        }
        let _ = rayon::ThreadPoolBuilder::new()
            .num_threads(limit)
            .build_global();
    });
}

#[cfg(all(feature = "parallel", target_arch = "wasm32"))]
fn configure_parallelism() {
    // No-op on WASM: cannot set environment variables or configure rayon
}

#[cfg(all(feature = "parallel", not(target_arch = "wasm32")))]
const fn default_thread_budget(cpu_count: usize) -> usize {
    match cpu_count {
        0..=2 => 1,
        3..=4 => 2,
        5..=7 => 4,
        _ => 8,
    }
}

#[cfg(not(feature = "parallel"))]
fn configure_parallelism() {}

const fn clamp01(value: f32) -> f32 {
    value.clamp(0.0, 1.0)
}

fn toroidal_delta(a: f32, b: f32, extent: f32) -> f32 {
    let mut delta = a - b;
    let half = extent * 0.5;
    if delta > half {
        delta -= extent;
    } else if delta < -half {
        delta += extent;
    }
    delta
}

fn angle_to(dx: f32, dy: f32) -> f32 {
    // `f32::atan2` delegates to the host C math library. Its last-bit result differs between
    // supported glibc releases, which changes eye inputs and eventually the scientific replay.
    // libm's pure-Rust implementation gives every native and Wasm target the same bearing.
    libm::atan2f(dy, dx)
}

#[cfg(test)]
fn angle_difference(a: f32, b: f32) -> f32 {
    let diff = wrap_signed_angle(a - b);
    diff.abs()
}

/// Legacy-parity blood-sensor contribution for one target.
///
/// The boundary is deliberately strict, matching `diff4 < PI38` in `World.cpp`. Within the
/// model's valid health interval `[0, 2]`, the wound term is exactly `1 - health / 2`; clamping is
/// retained only as a defensive Rust policy for invalid state outside that interval.
fn blood_sensor_contribution(
    forward_difference: f32,
    distance_factor: f32,
    target_health: f32,
) -> f32 {
    if !(0.0..BLOOD_HALF_FOV).contains(&forward_difference) || distance_factor <= 0.0 {
        return 0.0;
    }

    let angular_factor = (BLOOD_HALF_FOV - forward_difference) / BLOOD_HALF_FOV;
    let wound_factor = (1.0 - (target_health * 0.5).clamp(0.0, 1.0)).max(0.0);
    angular_factor * distance_factor * wound_factor
}

#[derive(Debug, Clone, Copy)]
struct SenseObserverGeometry {
    eye_units: [[f32; 2]; NUM_EYES],
    eye_fov: [f32; NUM_EYES],
    heading_unit: [f32; 2],
    eye_sensitivity: f32,
    radius: f32,
}

#[derive(Debug, Clone, Copy)]
struct SenseNeighborInputs {
    dx: f32,
    dy: f32,
    distance: f32,
    distance_factor: f32,
    color: [f32; 3],
    wheel_effort: f32,
    sound_emitter: f32,
    target_health: f32,
}

#[inline]
fn sense_distance_terms(
    distance_squared: f32,
    radius: f32,
    radius_squared: f32,
) -> Option<(f32, f32)> {
    if distance_squared <= f32::EPSILON || distance_squared > radius_squared {
        return None;
    }
    let distance = distance_squared.sqrt();
    let distance_factor = (radius - distance) / radius;
    (distance_factor > 0.0).then_some((distance, distance_factor))
}

// bd-tqpj: pinned FP evaluation order for the WGSL-lane parity contract; fma fusion
// would alter sensor contribution bytes.
#[allow(clippy::suboptimal_flops)]
fn fixed_sense_contribution(
    observer: &SenseObserverGeometry,
    neighbor: SenseNeighborInputs,
) -> sense_fixed::NeighborContribution {
    // Keep the operation sequence identical to the planned WGSL lane. A
    // reciprocal followed by multiplication can round differently from the
    // shader's explicit division and would defeat an otherwise exact contract.
    let neighbor_x = neighbor.dx / neighbor.distance;
    let neighbor_y = neighbor.dy / neighbor.distance;
    let mut contribution = sense_fixed::NeighborContribution {
        smell: neighbor.distance_factor,
        sound: neighbor.distance_factor * neighbor.wheel_effort,
        hearing: neighbor.distance_factor * neighbor.sound_emitter,
        ..sense_fixed::NeighborContribution::default()
    };

    for eye in 0..NUM_EYES {
        let eye_unit = observer.eye_units[eye];
        let dot = eye_unit[0] * neighbor_x + eye_unit[1] * neighbor_y;
        let difference = sense_fixed::poly_acos(dot.clamp(-1.0, 1.0));
        let fov = observer.eye_fov[eye];
        if difference >= fov {
            continue;
        }
        let fov_factor = ((fov - difference) / fov).max(0.0);
        let intensity = observer.eye_sensitivity * fov_factor * neighbor.distance_factor;
        contribution.density[eye] = intensity * (neighbor.distance / observer.radius);
        contribution.red[eye] = intensity * neighbor.color[0];
        contribution.green[eye] = intensity * neighbor.color[1];
        contribution.blue[eye] = intensity * neighbor.color[2];
    }

    let forward_dot = observer.heading_unit[0] * neighbor_x + observer.heading_unit[1] * neighbor_y;
    contribution.blood = blood_sensor_contribution(
        sense_fixed::poly_acos(forward_dot.clamp(-1.0, 1.0)),
        neighbor.distance_factor,
        neighbor.target_health,
    );
    contribution
}

#[inline]
fn dot2(ax: f32, ay: f32, bx: f32, by: f32) -> f32 {
    ax.mul_add(bx, ay * by)
}

/// Commands that can be applied to the world from external control surfaces.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum ControlCommand {
    /// Replace the live configuration.
    UpdateConfig(Box<ScriptBotsConfig>),
    /// Apply a selection change.
    UpdateSelection(SelectionUpdate),
    /// Playback control for the external simulation driver.
    UpdateSimulation(SimulationCommand),
    /// Pause simulation playback.
    Pause,
    /// Resume simulation playback.
    Resume,
    /// Advance simulation by one tick.
    Step,
    /// Set target simulation playback speed.
    SetSpeed(f32),
    /// Request simulation shutdown.
    Shutdown,
}

/// Playback command carried to the external simulation driver.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct SimulationCommand {
    /// Requested pause state, if the command changes it.
    pub paused: Option<bool>,
    /// Requested playback speed multiplier, if the command changes it.
    pub speed_multiplier: Option<f32>,
    /// Whether to advance exactly one tick.
    pub step_once: bool,
}

impl SimulationCommand {
    /// Validate values supplied by renderer and control front-ends before queue admission.
    pub const fn validate(&self) -> Result<(), WorldStateError> {
        if let Some(speed) = self.speed_multiplier
            && !speed.is_finite()
        {
            return Err(WorldStateError::InvalidConfig(
                "speed_multiplier must be finite",
            ));
        }
        Ok(())
    }

    /// Validate and normalize playback input for an external simulation driver.
    pub fn into_normalized(mut self) -> Result<Self, WorldStateError> {
        self.validate()?;
        if let Some(speed) = self.speed_multiplier.as_mut() {
            *speed = speed.clamp(0.0, 32.0);
        }
        Ok(self)
    }
}

/// Result of evaluating a control command against world state.
#[derive(Debug, Clone, PartialEq)]
pub enum ControlDisposition {
    /// World state modified; no playback changes required.
    WorldApplied,
    /// Playback portion returned to the external driver.
    Playback(SimulationCommand),
}

impl ControlCommand {
    /// Validate state-changing input without mutating the world or admitting queue work.
    pub fn validate(&self) -> Result<(), WorldStateError> {
        match self {
            Self::UpdateConfig(config) => config.validate(),
            Self::UpdateSelection(_) => Ok(()),
            Self::UpdateSimulation(command) => command.validate(),
            Self::Pause | Self::Resume | Self::Step | Self::Shutdown => Ok(()),
            Self::SetSpeed(speed) => {
                if !speed.is_finite() || *speed < 0.0 {
                    Err(WorldStateError::InvalidConfig(
                        "speed_multiplier must be finite and non-negative",
                    ))
                } else {
                    Ok(())
                }
            }
        }
    }
}

/// Apply the world-owned portion of a command and return playback for the external driver.
pub fn apply_control_command(
    world: &mut WorldState,
    command: ControlCommand,
) -> Result<ControlDisposition, WorldStateError> {
    command.validate()?;
    match command {
        ControlCommand::UpdateConfig(config) => {
            world.apply_config_update(*config)?;
            Ok(ControlDisposition::WorldApplied)
        }
        ControlCommand::UpdateSelection(update) => {
            let _ = world.apply_selection_update(update);
            Ok(ControlDisposition::WorldApplied)
        }
        ControlCommand::UpdateSimulation(update) => {
            Ok(ControlDisposition::Playback(update.into_normalized()?))
        }
        ControlCommand::Pause => Ok(ControlDisposition::Playback(SimulationCommand {
            paused: Some(true),
            speed_multiplier: None,
            step_once: false,
        })),
        ControlCommand::Resume => Ok(ControlDisposition::Playback(SimulationCommand {
            paused: Some(false),
            speed_multiplier: None,
            step_once: false,
        })),
        ControlCommand::Step => Ok(ControlDisposition::Playback(SimulationCommand {
            paused: None,
            speed_multiplier: None,
            step_once: true,
        })),
        ControlCommand::SetSpeed(speed) => Ok(ControlDisposition::Playback(SimulationCommand {
            paused: None,
            speed_multiplier: Some(speed.clamp(0.0, 32.0)),
            step_once: false,
        })),
        ControlCommand::Shutdown => Ok(ControlDisposition::WorldApplied),
    }
}

// bd-tqpj: pinned FP evaluation order; fma fusion would alter digests.
#[allow(clippy::suboptimal_flops)]
fn lerp(a: f32, b: f32, t: f32) -> f32 {
    a + (b - a) * t
}

/// Legacy's dead-zone threshold, in the SQUARED discomfort domain.
///
/// `World.cpp:95-100` computes the health drain as:
///
/// ```text
///   dd         = 2 * |pos.x / WIDTH - 0.5|      // 0 at the equator, 1 at the edges
///   discomfort = |dd - temperature_preference|
///   discomfort = discomfort * discomfort         // SQUARED FIRST
///   if (discomfort < 0.08) discomfort = 0;       // ...and the gate is on the SQUARE
///   health -= TEMPERATURE_DISCOMFORT * discomfort
/// ```
///
/// The gate is applied to the SQUARE, so in the raw domain it opens at
/// `sqrt(0.08)` — see [`DEFAULT_TEMPERATURE_COMFORT_BAND`]. Porting the literal
/// `0.08` into a raw-domain comparison, as this codebase did, silently shrinks
/// the comfort zone by a factor of ~3.5 and drains health from agents legacy
/// considered perfectly comfortable. Same magic number; different meaning.
pub const LEGACY_COMFORT_BAND_SQUARED: f32 = 0.08;

/// The comfort band, in the RAW discomfort domain: `sqrt(0.08)`.
///
/// This is the width legacy actually intended (see [`LEGACY_COMFORT_BAND_SQUARED`]).
///
/// # Parity versus policy — the decision, stated once
///
/// Two things differ from legacy, and only one of them is deliberate:
///
/// - **Deliberate policy.** Beyond the band, the drain scales with the EXCESS
///   discomfort (`(d - band)^exponent`), not the full discomfort. Legacy jumps
///   discontinuously from zero to `0.08 * rate` the instant the gate opens. That
///   cliff is an artefact of writing the gate as an `if`, not a modelling
///   intent, and a step change in a health drain puts a sharp, arbitrary
///   selection boundary in the middle of the temperature axis. The continuous
///   ramp is kept.
/// - **A defect, now fixed.** The band CONSTANT was ported across domains
///   unchanged, which is the bug documented above.
///
/// # The contract
///
/// - **Units.** Temperature and preference are both dimensionless, in `[0, 1]`.
///   `0` is the equator (the middle of the world), `1` is the east/west edges.
/// - **Formula.** `T(x) = (2 * |x/W - 0.5|) ^ gradient_exponent`, clamped to
///   `[0, 1]`. The default exponent of `1.0` is exactly legacy's linear gradient.
/// - **Cadence.** Once per tick, in `stage_temperature_discomfort`.
/// - **RNG inputs: NONE.** Temperature is a pure function of position and config.
///   This is a property worth protecting: a climate that consumed entropy would
///   make every run's weather a function of how many other draws happened first.
/// - **Bounds.** Every intermediate and every result is finite; a degenerate
///   (zero-width) world reports a uniform `0.5` rather than dividing by zero.
/// - **Default drain rate is 0.0**, exactly as in legacy (`TEMPERATURE_DISCOMFORT
///   = 0`), so the whole mechanism is inert unless a scenario turns it on — which
///   is why correcting the band moves no default digest.
pub const DEFAULT_TEMPERATURE_COMFORT_BAND: f32 = 0.282_842_7;

/// Legacy's health drain, transcribed exactly from `World.cpp:95-100`.
///
/// The micro-oracle. It exists to be DIFFERENT from the code under test where we
/// have chosen to differ, and identical where we have not — a parity claim that
/// cannot be checked against the thing it claims parity with is just an assertion.
#[must_use]
// bd-tqpj: exact legacy transcription; FP evaluation order and comparisons pinned.
#[allow(clippy::suboptimal_flops, clippy::imprecise_flops, clippy::float_cmp)]
pub fn legacy_temperature_health_drain(
    normalized_x: f32,
    preference: f32,
    discomfort_rate: f32,
) -> f32 {
    let dd = 2.0 * (normalized_x - 0.5).abs();
    let mut discomfort = (dd - preference).abs();
    discomfort *= discomfort;
    if discomfort < LEGACY_COMFORT_BAND_SQUARED {
        discomfort = 0.0;
    }
    discomfort_rate * discomfort
}

// bd-tqpj: u32→f32 world-width cast is the legacy grid contract; pinned (a wider
// intermediate would drift the gradient).
#[allow(clippy::cast_precision_loss)]
fn sample_temperature(config: &ScriptBotsConfig, x: f32) -> f32 {
    if config.world_width == 0 {
        return 0.5;
    }
    let width = config.world_width as f32;
    if width <= f32::EPSILON {
        return 0.5;
    }
    let normalized = (x / width).rem_euclid(1.0);
    let distance = ((normalized - 0.5).abs() * 2.0).clamp(0.0, 1.0);
    let exponent = config.temperature_gradient_exponent.max(f32::EPSILON);
    distance.powf(exponent).clamp(0.0, 1.0)
}

fn temperature_discomfort(env_temperature: f32, preference: f32) -> f32 {
    (env_temperature - clamp01(preference)).abs()
}

#[derive(Default, Clone)]
struct RunningStats {
    count: usize,
    mean: f64,
    m2: f64,
}

impl RunningStats {
    // bd-tqpj: Welford recurrence; FP evaluation order and usize→f64 count cast pinned
    // for determinism.
    #[allow(
        clippy::imprecise_flops,
        clippy::cast_precision_loss,
        clippy::suboptimal_flops
    )]
    fn update(&mut self, value: f64) {
        self.count += 1;
        let delta = value - self.mean;
        self.mean += delta / self.count as f64;
        let delta2 = value - self.mean;
        self.m2 += delta * delta2;
    }

    const fn mean(&self) -> f64 {
        self.mean
    }

    // bd-tqpj: usize→f64 count cast pinned for deterministic series encoding.
    #[allow(clippy::cast_precision_loss)]
    fn variance(&self) -> f64 {
        if self.count > 1 {
            self.m2 / (self.count - 1) as f64
        } else {
            0.0
        }
    }

    fn stddev(&self) -> f64 {
        self.variance().sqrt()
    }
}

// bd-tqpj: usize→f64 count cast and FP evaluation order pinned for deterministic series.
#[allow(clippy::cast_precision_loss, clippy::suboptimal_flops)]
fn summarize_signal(values: &[f32]) -> (f64, f64, f64) {
    if values.is_empty() {
        return (0.0, 0.0, 0.0);
    }
    let len = values.len() as f64;
    let mut sum = 0.0f64;
    let mut max = 0.0f32;
    let mut positive_sum = 0.0f64;
    for &value in values {
        let v = f64::from(value);
        sum += v;
        let magnitude = value.abs();
        if magnitude > max {
            max = magnitude;
        }
        if value > 0.0 {
            positive_sum += f64::from(value);
        } else if value < 0.0 {
            positive_sum += f64::from(-value);
        }
    }
    let mean = sum / len;
    let peak = f64::from(max);

    if positive_sum <= f64::EPSILON {
        return (mean, peak, 0.0);
    }

    let mut entropy = 0.0f64;
    for &value in values {
        let weight = f64::from(value.abs()) / positive_sum;
        if weight > 0.0 {
            entropy -= weight * weight.ln();
        }
    }
    (mean, peak, entropy)
}

fn sanitize_metric_key(label: &str) -> String {
    let mut result = String::with_capacity(label.len());
    for ch in label.chars() {
        if ch.is_ascii_alphanumeric() {
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push('_');
        }
    }
    result
}

// bd-tqpj: usize→f64 count cast and FP evaluation order pinned for deterministic series.
#[allow(clippy::cast_precision_loss, clippy::suboptimal_flops)]
fn summarize_food_grid(cells: &[f32]) -> Option<(f64, f64, f64, f32)> {
    if cells.is_empty() {
        return None;
    }
    let mut sum = 0.0f64;
    let mut sum_sq = 0.0f64;
    let mut max = f32::MIN;
    for &value in cells {
        let v = f64::from(value);
        sum += v;
        sum_sq += v * v;
        if value > max {
            max = value;
        }
    }
    let count = cells.len() as f64;
    let mean = sum / count;
    let variance = if count > 1.0 {
        (sum_sq - sum * mean) / (count - 1.0)
    } else {
        0.0
    };
    Some((sum, mean, variance.max(0.0), max))
}

