/// Runtime brain attachment tracking.
///
/// Protocol and legacy execution are mutually exclusive by construction. Admitted evolutionary
/// families use `Protocol`; `Legacy` exists only for explicitly non-admitted adapters and tests
/// while they migrate. Keeping these as enum variants prevents a genome from being evaluated by
/// an unrelated legacy runner or silently falling back to fresh random construction.
#[derive(Serialize, Deserialize)]
pub enum BrainBinding {
    /// No brain attached.
    Unbound,
    /// Admitted evolutionary family binding.
    Protocol {
        /// Registry key of the bound brain family.
        registry_key: u64,
        /// Brain family kind identifier.
        kind: String,
        /// Heritable genome envelope.
        genome: BrainGenomeEnvelope,
        /// Live evaluator state (never serialized).
        #[serde(skip)]
        evaluator: Option<Box<dyn BrainEvaluator>>,
    },
    /// Non-admitted legacy runner binding.
    Legacy {
        /// Live legacy runner (never serialized).
        #[serde(skip)]
        runner: Option<Box<dyn BrainRunner>>,
        /// Legacy registry key, if registered.
        registry_key: Option<u64>,
        /// Legacy brain kind identifier.
        kind: String,
    },
}

enum BrainExecution {
    None,
    MissingLegacy(Option<u64>),
    MissingProtocol(BrainFamilyId),
    Protocol(Box<dyn BrainEvaluator>),
    Legacy(Box<dyn BrainRunner>),
}

impl Default for BrainBinding {
    fn default() -> Self {
        Self::unbound()
    }
}

impl Clone for BrainBinding {
    fn clone(&self) -> Self {
        match self {
            Self::Unbound => Self::Unbound,
            Self::Protocol {
                registry_key,
                kind,
                genome,
                evaluator: _,
            } => Self::Protocol {
                registry_key: *registry_key,
                kind: kind.clone(),
                genome: genome.clone(),
                evaluator: None,
            },
            Self::Legacy {
                runner: _,
                registry_key,
                kind,
            } => Self::Legacy {
                runner: None,
                registry_key: *registry_key,
                kind: kind.clone(),
            },
        }
    }
}

impl fmt::Debug for BrainBinding {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unbound => f.debug_tuple("BrainBinding::Unbound").finish(),
            Self::Protocol {
                registry_key,
                kind,
                genome,
                evaluator,
            } => f
                .debug_struct("BrainBinding::Protocol")
                .field("registry_key", registry_key)
                .field("kind", kind)
                .field("family_id", genome.family_id())
                .field("material_hash", &genome.material_hash())
                .field("live", &evaluator.is_some())
                .finish(),
            Self::Legacy {
                runner,
                registry_key,
                kind,
            } => f
                .debug_struct("BrainBinding::Legacy")
                .field("registry_key", registry_key)
                .field("kind", kind)
                .field("live", &runner.is_some())
                .finish(),
        }
    }
}

impl BrainBinding {
    /// Construct an unbound brain attachment.
    #[must_use]
    pub const fn unbound() -> Self {
        Self::Unbound
    }

    /// Attach a brain runner produced outside the registry.
    #[must_use]
    pub fn with_runner(runner: Box<dyn BrainRunner>) -> Self {
        let kind = runner.kind().to_string();
        Self::Legacy {
            runner: Some(runner),
            registry_key: None,
            kind,
        }
    }

    /// Instantiate a legacy runner entry from the registry and bind it to the agent.
    ///
    /// Protocol entries require caller-owned provenance and evaluator state, so live-world code
    /// constructs them through `WorldState`'s admitted-family path instead.
    ///
    /// # Panics
    ///
    /// Panics if the registry spawned a runner for `key` yet no longer retains the entry's kind;
    /// that combination violates the registry's spawn-retains-kind invariant.
    pub fn from_registry(
        registry: &BrainRegistry,
        rng: &mut dyn RandomStream,
        key: u64,
    ) -> Result<Option<Self>, BrainSpawnError> {
        let Some(runner) = registry.spawn(rng, key)? else {
            return Ok(None);
        };
        let kind = registry
            .kind(key)
            .expect("a spawned registry entry must retain its kind")
            .to_owned();
        Ok(Some(Self::Legacy {
            runner: Some(runner),
            registry_key: Some(key),
            kind,
        }))
    }

    /// Attach an inherited runner while preserving the family registry key,
    /// so later generations can still fall back to the registry factory.
    #[must_use]
    pub fn inherited(runner: Box<dyn BrainRunner>, registry_key: Option<u64>) -> Self {
        let kind = runner.kind().to_string();
        Self::Legacy {
            runner: Some(runner),
            registry_key,
            kind,
        }
    }

    fn protocol(
        registry_key: u64,
        kind: String,
        genome: BrainGenomeEnvelope,
        evaluator: Box<dyn BrainEvaluator>,
    ) -> Self {
        Self::Protocol {
            registry_key,
            kind,
            genome,
            evaluator: Some(evaluator),
        }
    }

    /// Borrow the live runner, if any.
    #[must_use]
    pub fn runner(&self) -> Option<&dyn BrainRunner> {
        match self {
            Self::Legacy { runner, .. } => runner.as_deref(),
            Self::Unbound | Self::Protocol { .. } => None,
        }
    }

    /// Return the semantic registry identity, even when no live executor is attached.
    #[must_use]
    pub const fn registry_key(&self) -> Option<u64> {
        match self {
            Self::Unbound => None,
            Self::Protocol { registry_key, .. } => Some(*registry_key),
            Self::Legacy { registry_key, .. } => *registry_key,
        }
    }

    /// Return the semantic brain-family identity, even when no live executor is attached.
    #[must_use]
    pub fn kind(&self) -> Option<&str> {
        match self {
            Self::Unbound => None,
            Self::Protocol { kind, .. } | Self::Legacy { kind, .. } => Some(kind),
        }
    }

    /// Whether a live protocol evaluator or legacy runner is currently attached.
    #[must_use]
    pub fn is_bound(&self) -> bool {
        match self {
            Self::Unbound => false,
            Self::Protocol { evaluator, .. } => evaluator.is_some(),
            Self::Legacy { runner, .. } => runner.is_some(),
        }
    }

    /// Exact protocol genome when this is an admitted evolutionary family.
    #[must_use]
    pub const fn genome(&self) -> Option<&BrainGenomeEnvelope> {
        match self {
            Self::Protocol { genome, .. } => Some(genome),
            Self::Unbound | Self::Legacy { .. } => None,
        }
    }

    fn checkpoint_evaluator_state_with(
        &self,
        adapter: &dyn BrainFamilyAdapter,
    ) -> Result<Option<BrainEvaluatorStateEnvelope>, BrainSpawnError> {
        match self {
            Self::Protocol {
                kind,
                genome,
                evaluator,
                ..
            } => {
                adapter
                    .validate_genome(genome)
                    .map_err(|error| BrainSpawnError::new(kind.clone(), error))?;
                let evaluator = evaluator.as_ref().ok_or_else(|| {
                    BrainSpawnError::new(
                        kind.clone(),
                        MissingProtocolEvaluator {
                            family_id: genome.family_id().clone(),
                        },
                    )
                })?;
                adapter
                    .checkpoint_evaluator_for_genome(genome, evaluator.as_ref())
                    .map(Some)
                    .map_err(|error| BrainSpawnError::new(kind.clone(), error))
            }
            Self::Unbound | Self::Legacy { .. } => Ok(None),
        }
    }

    /// Produce a short semantic identity descriptor suitable for persistence logs.
    ///
    /// This deliberately does not claim executable liveness: executor-free clones are normal
    /// read-model snapshots. Call [`Self::is_bound`] when the live execution attachment matters.
    #[must_use]
    pub fn describe(&self) -> Cow<'_, str> {
        self.registry_key().map_or_else(
            || self.kind().map_or(Cow::Borrowed("unbound"), Cow::Borrowed),
            |key| Cow::Owned(format!("registry:{key}")),
        )
    }

    /// Perform one explicit bounded read-only inspection if supported by the runner.
    pub fn inspect(
        &self,
        request: BrainInspection,
    ) -> Result<Option<BrainInspectionSnapshot>, BrainInspectionError> {
        match self {
            Self::Unbound => Ok(None),
            Self::Protocol { evaluator, .. } => evaluator
                .as_ref()
                .map_or(Ok(None), |evaluator| evaluator.inspect(request)),
            Self::Legacy { runner, .. } => runner
                .as_ref()
                .map_or(Ok(None), |runner| runner.inspect(request)),
        }
    }

    fn take_execution(&mut self) -> BrainExecution {
        match self {
            Self::Unbound => BrainExecution::None,
            Self::Protocol {
                genome, evaluator, ..
            } => evaluator.take().map_or_else(
                || BrainExecution::MissingProtocol(genome.family_id().clone()),
                BrainExecution::Protocol,
            ),
            Self::Legacy {
                runner,
                registry_key,
                ..
            } => runner.take().map_or(
                BrainExecution::MissingLegacy(*registry_key),
                BrainExecution::Legacy,
            ),
        }
    }

    fn restore_execution(&mut self, execution: BrainExecution) {
        match (self, execution) {
            (Self::Unbound, BrainExecution::None)
            | (Self::Legacy { .. }, BrainExecution::MissingLegacy(_))
            | (Self::Protocol { .. }, BrainExecution::MissingProtocol(_)) => {}
            (Self::Protocol { evaluator, .. }, BrainExecution::Protocol(restored)) => {
                debug_assert!(evaluator.is_none());
                *evaluator = Some(restored);
            }
            (Self::Legacy { runner, .. }, BrainExecution::Legacy(restored)) => {
                debug_assert!(runner.is_none());
                *runner = Some(restored);
            }
            _ => unreachable!("brain execution variant changed while detached"),
        }
    }

    fn state_digest(&self) -> Option<u64> {
        match self {
            Self::Unbound => None,
            Self::Legacy { runner, .. } => runner.as_deref().and_then(BrainRunner::state_digest),
            Self::Protocol {
                genome, evaluator, ..
            } => {
                let state = evaluator.as_ref()?.checkpoint_state().ok()?;
                let mut hasher = blake3::Hasher::new_derive_key(
                    "rust-scriptbots.brain-genome-and-evaluator-state.v1",
                );
                hasher.update(genome.material_hash().as_bytes());
                let family = state.family_id().as_str().as_bytes();
                hasher.update(&(family.len() as u64).to_le_bytes());
                hasher.update(family);
                hasher.update(&state.schema_version().to_le_bytes());
                hasher.update(&state.codec_version().to_le_bytes());
                hasher.update(&(state.payload().len() as u64).to_le_bytes());
                hasher.update(state.payload());
                Some(u64::from_le_bytes(
                    hasher.finalize().as_bytes()[..8]
                        .try_into()
                        .expect("BLAKE3 output always has eight prefix bytes"),
                ))
            }
        }
    }
}

/// Thin trait object used to drive brain evaluations without coupling to concrete brain crates.
pub trait BrainRunner: Send + Sync {
    /// Static identifier of the brain implementation.
    fn kind(&self) -> &'static str;

    /// Evaluate outputs for the provided sensors.
    fn tick(&mut self, inputs: &[f32; INPUT_SIZE]) -> [f32; OUTPUT_SIZE];

    /// Optional bounded read-only state for an explicit visualization request.
    /// Defaults to `None` when the runner does not support introspection.
    fn inspect(
        &self,
        _request: BrainInspection,
    ) -> Result<Option<BrainInspectionSnapshot>, BrainInspectionError> {
        Ok(None)
    }

    /// Stable digest of everything this brain CARRIES — its genome and its evaluator state.
    ///
    /// This is what `CharacterizationDigestV0` cannot see. That digest encodes a brain's registry
    /// key, its family name, and whether it is bound — and nothing else. So two worlds whose
    /// agents have been evolving for a million ticks into completely different brains produce the
    /// SAME v0 digest, as long as the families and bindings match. The oracle that decides whether
    /// two runs are the same run is blind to the only thing that is actually evolving.
    ///
    /// That limitation is declared rather than hidden (`RunManifestV3`'s
    /// `CharacterizationLimitationsV0::evaluator_state_covered = false`, `superseded_by:
    /// WorldDigestV1`), and this method is how `WorldDigestV1` closes it.
    ///
    /// `None` means the family cannot expose its state. That is permitted — but it is NOT
    /// silently permitted: a `WorldDigestV1` computed over a world containing such a family
    /// reports `evaluator_state_covered = false` and names the family. An omission the reader
    /// cannot see is precisely the failure this whole lane exists to remove.
    fn state_digest(&self) -> Option<u64> {
        None
    }

    /// Duplicate this runner including all evolved parameters.
    ///
    /// `None` marks the family as non-heritable; reproduction then falls back
    /// to spawning a fresh runner from the registry. An exact-snapshot failure
    /// is returned as an error and must never be normalized into `None`.
    fn clone_runner(&self) -> Result<Option<Box<dyn BrainRunner>>, BrainSpawnError> {
        Ok(None)
    }

    /// Perturb parameters in place using the agent's mutation rates.
    fn mutate(
        &mut self,
        _rng: &mut dyn RandomStream,
        _rate: f32,
        _scale: f32,
    ) -> Result<(), BrainSpawnError> {
        Ok(())
    }

    /// Produce an offspring runner by recombining with a same-kind partner.
    fn crossover(
        &self,
        _partner: &dyn BrainRunner,
        _rng: &mut dyn RandomStream,
    ) -> Option<Box<dyn BrainRunner>> {
        None
    }

    /// Downcast hook so cross-crate `crossover` implementations can identify
    /// same-family partners behind the trait object.
    fn as_any(&self) -> Option<&(dyn Any + Send + Sync)> {
        None
    }
}

/// Typed failure returned by a registered brain family during construction or evaluation.
#[derive(Debug, Clone)]
pub struct BrainSpawnError {
    kind: Cow<'static, str>,
    source: std::sync::Arc<dyn std::error::Error + Send + Sync>,
}

impl std::fmt::Display for BrainSpawnError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "brain family `{}` failed: {}", self.kind, self.source)
    }
}

impl std::error::Error for BrainSpawnError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(self.source.as_ref())
    }
}

impl BrainSpawnError {
    /// Attach a concrete adapter error to its registered brain-family label.
    pub fn new<E>(kind: impl Into<Cow<'static, str>>, source: E) -> Self
    where
        E: std::error::Error + Send + Sync + 'static,
    {
        Self {
            kind: kind.into(),
            source: std::sync::Arc::new(source),
        }
    }

    /// Brain-family label whose construction or evaluation failed.
    #[must_use]
    pub fn kind(&self) -> &str {
        self.kind.as_ref()
    }
}

#[derive(Debug, Error)]
#[error("brain registry key {key} disappeared before offspring construction")]
struct MissingBrainFactory {
    key: u64,
}

#[derive(Debug, Error)]
#[error("bound parent has no exact heritable snapshot and no registry fallback")]
struct MissingHeritableBrain;

#[derive(Debug, Error)]
#[error("legacy brain binding has no live runner (registry_key={registry_key:?})")]
struct MissingLegacyRunner {
    registry_key: Option<u64>,
}

#[derive(Debug, Error)]
#[error("protocol brain `{family_id}` has no live evaluator at offspring preparation")]
struct MissingProtocolEvaluator {
    family_id: BrainFamilyId,
}

type BrainSpawner = Box<
    dyn Fn(&mut dyn RandomStream) -> Result<Box<dyn BrainRunner>, BrainSpawnError>
        + Send
        + Sync
        + 'static,
>;

struct BrainEntry {
    kind: Cow<'static, str>,
    factory_state_digest: Option<u64>,
    adapter_identity: Option<BrainAdapterIdentityV1>,
    spawner: Option<BrainSpawner>,
    protocol_adapter: Option<Box<dyn BrainFamilyAdapter>>,
}

/// Registry owning brain runners keyed by opaque handles.
#[derive(Default)]
pub struct BrainRegistry {
    next_key: u64,
    entries: HashMap<u64, BrainEntry>,
}

impl std::fmt::Debug for BrainRegistry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("BrainRegistry")
            .field("next_key", &self.next_key)
            .field("entry_count", &self.entries.len())
            .finish()
    }
}

impl BrainRegistry {
    /// Construct an empty registry.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Registers a fallible brain factory, returning its registry key.
    pub fn register<F>(&mut self, kind: impl Into<Cow<'static, str>>, factory: F) -> u64
    where
        F: Fn(&mut dyn RandomStream) -> Result<Box<dyn BrainRunner>, BrainSpawnError>
            + Send
            + Sync
            + 'static,
    {
        self.register_inner(kind, None, factory)
    }

    /// Registers a factory together with a stable digest of captured construction state.
    ///
    /// The supplied digest must change whenever captured seeds, model bytes, architecture
    /// settings, or other closure state capable of changing a newly spawned brain changes.
    /// Factories registered through [`Self::register`] remain valid, but V1.4 and later reports
    /// their closure state as explicitly uncovered.
    pub fn register_with_state_digest<F>(
        &mut self,
        kind: impl Into<Cow<'static, str>>,
        factory_state_digest: u64,
        factory: F,
    ) -> u64
    where
        F: Fn(&mut dyn RandomStream) -> Result<Box<dyn BrainRunner>, BrainSpawnError>
            + Send
            + Sync
            + 'static,
    {
        self.register_inner(kind, Some(factory_state_digest), factory)
    }

    fn register_inner<F>(
        &mut self,
        kind: impl Into<Cow<'static, str>>,
        factory_state_digest: Option<u64>,
        factory: F,
    ) -> u64
    where
        F: Fn(&mut dyn RandomStream) -> Result<Box<dyn BrainRunner>, BrainSpawnError>
            + Send
            + Sync
            + 'static,
    {
        let key = self.next_key;
        self.next_key += 1;
        self.entries.insert(
            key,
            BrainEntry {
                kind: kind.into(),
                factory_state_digest,
                adapter_identity: None,
                spawner: Some(Box::new(factory)),
                protocol_adapter: None,
            },
        );
        key
    }

    /// Register one versioned family adapter as an admitted evolutionary family.
    ///
    /// Protocol entries do not expose a legacy runner factory: callers must construct an exact
    /// genome, evaluator state, and evaluator through the adapter contract.
    pub fn register_family(
        &mut self,
        kind: impl Into<Cow<'static, str>>,
        adapter: Box<dyn BrainFamilyAdapter>,
    ) -> Result<u64, BrainProtocolError> {
        let family_id = adapter.family_id().clone();
        let adapter_identity = adapter.adapter_identity();
        if self.entries.values().any(|entry| {
            entry
                .protocol_adapter
                .as_ref()
                .is_some_and(|registered| registered.family_id() == &family_id)
        }) {
            return Err(BrainProtocolError::DuplicateFamily { family_id });
        }

        let key = self.next_key;
        self.next_key += 1;
        self.entries.insert(
            key,
            BrainEntry {
                kind: kind.into(),
                factory_state_digest: None,
                adapter_identity: Some(adapter_identity),
                spawner: None,
                protocol_adapter: Some(adapter),
            },
        );
        Ok(key)
    }

    /// Removes a brain factory from the registry.
    pub fn unregister(&mut self, key: u64) -> bool {
        self.entries.remove(&key).is_some()
    }

    /// Instantiate a new brain runner using the factory referenced by `key`.
    pub fn spawn(
        &self,
        rng: &mut dyn RandomStream,
        key: u64,
    ) -> Result<Option<Box<dyn BrainRunner>>, BrainSpawnError> {
        self.entries
            .get(&key)
            .and_then(|entry| entry.spawner.as_ref())
            .map_or(Ok(None), |spawner| spawner(rng).map(Some))
    }

    /// Borrow the admitted protocol adapter registered at `key`.
    #[must_use]
    pub fn family(&self, key: u64) -> Option<&dyn BrainFamilyAdapter> {
        self.entries
            .get(&key)
            .and_then(|entry| entry.protocol_adapter.as_deref())
    }

    /// Stable family-owned semantic identity captured when the protocol adapter was admitted.
    #[must_use]
    pub fn adapter_identity(&self, key: u64) -> Option<BrainAdapterIdentityV1> {
        self.entries
            .get(&key)
            .and_then(|entry| entry.adapter_identity)
    }

    /// Whether `key` selects a versioned protocol family rather than a legacy runner factory.
    #[must_use]
    pub fn is_protocol_family(&self, key: u64) -> bool {
        self.family(key).is_some()
    }

    /// Retrieve the descriptive identifier associated with a registry entry.
    #[must_use]
    pub fn kind(&self, key: u64) -> Option<&str> {
        self.entries.get(&key).map(|entry| entry.kind.as_ref())
    }

    /// Returns whether a key is registered.
    #[must_use]
    pub fn contains(&self, key: u64) -> bool {
        self.entries.contains_key(&key)
    }

    /// Return registered brain keys and kind labels in stable key order.
    #[must_use]
    pub fn descriptors(&self) -> Vec<(u64, String)> {
        let mut descriptors: Vec<_> = self
            .entries
            .iter()
            .map(|(key, entry)| (*key, entry.kind.to_string()))
            .collect();
        descriptors.sort_unstable_by_key(|(key, _)| *key);
        descriptors
    }

    /// Pick a random registered brain key, if any.
    pub fn random_key(&self, rng: &mut dyn RandomStream) -> Option<u64> {
        if self.entries.is_empty() {
            return None;
        }
        // Once at least one honest protocol family exists, legacy factories are explicit-only:
        // population maintenance must not silently inject a non-protocol brain into an evolving
        // scenario. Legacy-only test/transition worlds retain their historical selection path.
        let has_protocol_family = self
            .entries
            .values()
            .any(|entry| entry.protocol_adapter.is_some());
        let mut keys: Vec<u64> = self
            .entries
            .iter()
            .filter_map(|(key, entry)| {
                (!has_protocol_family || entry.protocol_adapter.is_some()).then_some(*key)
            })
            .collect();
        // Select from a sorted key list for stable ordering across hashseed/platforms.
        keys.sort_unstable();
        let idx = rng.random_range(0..keys.len());
        keys.get(idx).copied()
    }
}

