    #[test]
    fn trusted_crossover_rejects_same_or_missing_handles_without_state_drift() {
        let mut world = WorldState::new(ScriptBotsConfig {
            population_minimum: 0,
            population_spawn_interval: 0,
            rng_seed: Some(0xC205_50A5),
            ..ScriptBotsConfig::default()
        })
        .expect("world");
        let live = world.spawn_agent(sample_agent(2));
        let missing = world.spawn_agent(sample_agent(5));
        let callback_calls = Cell::new(0usize);

        let same_tick_rng = world.random_streams_checkpoint();
        let same_tick_identity = world.identity_sequence_state();
        let same_tick_records = world.pending_birth_records.clone();
        let same_tick = world
            .try_inject_crossover_agent_with(live, missing, AgentData::default(), |_, _| {
                callback_calls.set(callback_calls.get() + 1);
            })
            .expect("same-boundary parent rejection is typed");
        assert_eq!(same_tick, None);
        assert_eq!(callback_calls.get(), 0);
        assert_eq!(world.random_streams_checkpoint(), same_tick_rng);
        assert_eq!(world.identity_sequence_state(), same_tick_identity);
        assert_eq!(world.pending_birth_records, same_tick_records);

        world.remove_agent(missing).expect("remove second parent");

        let rng_before = world.random_streams_checkpoint();
        let identity_before = world.identity_sequence_state();
        let records_before = world.pending_birth_records.clone();
        let agent_count_before = world.agent_count();

        let same = world
            .try_inject_crossover_agent_with(live, live, AgentData::default(), |_, _| {
                callback_calls.set(callback_calls.get() + 1);
            })
            .expect("same-parent rejection is typed");
        let stale = world
            .try_inject_crossover_agent_with(live, missing, AgentData::default(), |_, _| {
                callback_calls.set(callback_calls.get() + 1);
            })
            .expect("missing-parent rejection is typed");

        assert_eq!(same, None);
        assert_eq!(stale, None);
        assert_eq!(callback_calls.get(), 0);
        assert_eq!(world.random_streams_checkpoint(), rng_before);
        assert_eq!(world.identity_sequence_state(), identity_before);
        assert_eq!(world.pending_birth_records, records_before);
        assert_eq!(world.agent_count(), agent_count_before);
        assert!(world.pending_lifecycle_birth_metrics.is_empty());
        assert_eq!(world.last_births, 0);
    }

    #[test]
    fn external_origin_lineage_is_rejected_without_rng_allocator_or_record_drift() {
        let config = ScriptBotsConfig {
            population_minimum: 0,
            population_spawn_interval: 0,
            rng_seed: Some(0x011A_EA6E),
            ..ScriptBotsConfig::default()
        };
        let mut rejected = WorldState::new(config.clone()).expect("rejected world");
        let mut reference = WorldState::new(config).expect("reference world");
        let before_rng = rejected.random_streams_checkpoint();
        let before_identity = rejected.identity_sequence_state();
        let before_digest = rejected
            .characterization_digest_v0()
            .expect("pre-rejection digest");

        for injected in [false, true] {
            let result = if injected {
                rejected.try_inject_agent_with(sample_agent(1), |runtime| {
                    runtime.lineage = [Some(AgentUid(999)), None];
                })
            } else {
                rejected.try_spawn_agent_with(sample_agent(1), |runtime| {
                    runtime.lineage = [Some(AgentUid(999)), None];
                })
            };
            assert_eq!(
                result,
                Err(ScientificStateError::ExternalLineageMutation {
                    path: "agent.runtime.lineage".to_owned(),
                })
            );
            assert_eq!(rejected.agent_count(), 0);
            assert!(rejected.pending_birth_records.is_empty());
            assert_eq!(rejected.random_streams_checkpoint(), before_rng);
            assert_eq!(rejected.identity_sequence_state(), before_identity);
            assert_eq!(
                rejected
                    .characterization_digest_v0()
                    .expect("unchanged digest"),
                before_digest
            );
        }

        let actual = rejected
            .try_inject_agent(sample_agent(2))
            .expect("valid follow-up injection");
        let expected = reference
            .try_inject_agent(sample_agent(2))
            .expect("reference injection");
        assert_eq!(actual, expected);
        assert_eq!(
            rejected.random_streams_checkpoint(),
            reference.random_streams_checkpoint()
        );
        assert_eq!(
            rejected.identity_sequence_state(),
            reference.identity_sequence_state()
        );
        assert_eq!(
            rejected.pending_birth_records,
            reference.pending_birth_records
        );
    }

    #[test]
    fn same_tick_seed_metadata_tracks_successful_host_customization_only() {
        let mut world = WorldState::new(ScriptBotsConfig {
            population_minimum: 0,
            population_spawn_interval: 0,
            rng_seed: Some(0x5EED_DA7A),
            ..ScriptBotsConfig::default()
        })
        .expect("world");
        let key = world
            .brain_registry_mut()
            .expect("seed metadata registry mutation")
            .register("test.seed-metadata", |_rng| Ok(Box::new(StubBrain)));
        let id = world
            .try_spawn_agent(sample_agent(1))
            .expect("seeded founder");

        assert!(world.pending_birth_records[0].brain_key.is_none());
        assert!(world.bind_agent_brain(id, key).expect("bind founder"));
        assert_eq!(world.pending_birth_records[0].brain_key, Some(key));
        assert_eq!(
            world.pending_birth_records[0].brain_kind.as_deref(),
            Some("test.seed-metadata")
        );

        world
            .try_update_agent(id, |data, runtime| {
                data.position = Position::new(17.0, 19.0);
                data.generation = Generation(4);
                runtime.herbivore_tendency = 0.25;
                runtime.hybrid = true;
            })
            .expect("same-tick scalar/runtime update");
        assert!(world.pending_birth_records[0].is_hybrid);
        world
            .try_update_agent_runtime(id, |runtime| {
                runtime.herbivore_tendency = 0.75;
                runtime.hybrid = false;
            })
            .expect("same-tick runtime update");
        let record = &world.pending_birth_records[0];
        assert_eq!(record.position, Position::new(17.0, 19.0));
        assert_eq!(record.generation, Generation(4));
        assert!((record.herbivore_tendency - 0.75).abs() < f32::EPSILON);
        assert!(!record.is_hybrid);
        assert_eq!([record.parent_a, record.parent_b], [None, None]);

        let error = world
            .try_update_agent(id, |data, runtime| {
                data.position = Position::new(90.0, 91.0);
                runtime.lineage = [Some(AgentUid(41)), None];
            })
            .expect_err("combined update must reject lineage mutation atomically");
        assert_eq!(
            error,
            ScientificStateError::ExternalLineageMutation {
                path: format!("agents[{}].runtime.lineage", id.raw()),
            }
        );
        assert_eq!(
            world
                .snapshot_agent(id)
                .expect("unchanged agent")
                .data
                .position,
            Position::new(17.0, 19.0)
        );
        assert_eq!(world.agent_runtime(id).unwrap().lineage, [None, None]);

        let error = world
            .try_update_agent_runtime(id, |runtime| {
                runtime.herbivore_tendency = 0.1;
                runtime.lineage = [None, Some(AgentUid(42))];
            })
            .expect_err("runtime update must reject lineage mutation atomically");
        assert_eq!(
            error,
            ScientificStateError::ExternalLineageMutation {
                path: format!("agents[{}].runtime.lineage", id.raw()),
            }
        );
        assert!((world.agent_runtime(id).unwrap().herbivore_tendency - 0.75).abs() < f32::EPSILON);

        world.agent_runtime_mut(id).unwrap().lineage = [Some(AgentUid(123)), None];
        assert!(
            world
                .bind_agent_brain(id, key)
                .expect("same-tick metadata refresh")
        );
        assert_eq!(
            [
                world.pending_birth_records[0].parent_a,
                world.pending_birth_records[0].parent_b,
            ],
            [None, None],
            "metadata refresh must never rewrite insertion-time ancestry"
        );
        world.agent_runtime_mut(id).unwrap().lineage = [None, None];

        world.advance_tick();
        world
            .try_update_agent_runtime(id, |runtime| {
                runtime.herbivore_tendency = 0.9;
            })
            .expect("later runtime update");
        assert!(
            (world.pending_birth_records[0].herbivore_tendency - 0.75).abs() < f32::EPSILON,
            "a later tick must not rewrite immutable origin history"
        );
    }

    fn assert_non_finite_path(error: &ScientificStateError, expected_path: &str) {
        assert_eq!(error.path(), expected_path);
        assert!(matches!(error, ScientificStateError::NonFinite { .. }));
    }

    fn assert_dimension_overflow(error: WorldStateError, expected_path: &str) {
        assert!(
            matches!(&error, WorldStateError::InvalidState(_)),
            "expected typed scientific-state rejection, got {error}"
        );
        let WorldStateError::InvalidState(error) = error else {
            return;
        };
        assert_eq!(error.path(), expected_path);
        assert!(matches!(
            error,
            ScientificStateError::DimensionOverflow { .. }
        ));
    }

    #[test]
    fn direct_agent_ingress_rejects_each_non_finite_class_without_state_or_rng_drift() {
        for value in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            let config = ScriptBotsConfig {
                rng_seed: Some(0x5EA1_ED11),
                population_minimum: 0,
                population_spawn_interval: 0,
                ..ScriptBotsConfig::default()
            };
            let mut rejected = WorldState::new(config.clone()).expect("rejected world");
            let mut reference = WorldState::new(config).expect("reference world");
            let before = rejected
                .characterization_digest_v0()
                .expect("quiescent digest");
            let before_revision = rejected.config_revision();
            let before_audit = rejected.config_audit().to_vec();

            let error = rejected
                .try_spawn_agent(AgentData {
                    velocity: Velocity::new(0.25, value),
                    ..AgentData::default()
                })
                .expect_err("non-finite velocity must be rejected");
            assert_non_finite_path(&error, "agent.velocity.vy");
            assert_eq!(
                rejected
                    .characterization_digest_v0()
                    .expect("unchanged digest"),
                before
            );
            assert_eq!(rejected.config_revision(), before_revision);
            assert_eq!(rejected.config_audit(), before_audit);

            let error = rejected
                .try_spawn_agent_with(AgentData::default(), |runtime| {
                    runtime.outputs[2] = value;
                })
                .expect_err("non-finite runtime must reject the whole spawn");
            assert_non_finite_path(&error, "agent.runtime.outputs[2]");
            assert_eq!(
                rejected
                    .characterization_digest_v0()
                    .expect("unchanged runtime-rejection digest"),
                before
            );

            let rejected_id = rejected
                .try_spawn_agent(AgentData::default())
                .expect("finite follow-up spawn");
            let reference_id = reference
                .try_spawn_agent(AgentData::default())
                .expect("finite reference spawn");
            assert_eq!(rejected_id, reference_id, "allocator state must not drift");
            assert_eq!(
                rejected
                    .characterization_digest_v0()
                    .expect("follow-up digest"),
                reference
                    .characterization_digest_v0()
                    .expect("reference digest"),
                "rejection must not consume the fixed-seed random stream"
            );
        }
    }

    #[test]
    fn transactional_agent_and_food_updates_are_atomic_and_report_exact_indexes() {
        struct IngressTestBrain;
        impl BrainRunner for IngressTestBrain {
            fn kind(&self) -> &'static str {
                "ingress-test"
            }

            fn tick(&mut self, _inputs: &[f32; INPUT_SIZE]) -> [f32; OUTPUT_SIZE] {
                [0.0; OUTPUT_SIZE]
            }
        }

        let mut world = WorldState::new(ScriptBotsConfig {
            rng_seed: Some(0xA70C_1C11),
            population_minimum: 0,
            population_spawn_interval: 0,
            ..ScriptBotsConfig::default()
        })
        .expect("world");
        let agent = world
            .try_spawn_agent_with(AgentData::default(), |runtime| {
                runtime.energy = -0.0;
                runtime.sensors[INPUT_SIZE - 1] = f32::MIN_POSITIVE;
                runtime.brain = BrainBinding::with_runner(Box::new(IngressTestBrain));
            })
            .expect("representative finite boundaries are admitted");
        world
            .try_update_agent_runtime(agent, |runtime| runtime.energy = 0.75)
            .expect("finite runtime edit");
        assert!(
            world
                .agent_runtime(agent)
                .expect("runtime")
                .brain
                .is_bound(),
            "staging a finite runtime edit must preserve its non-cloneable live brain runner"
        );
        let baseline = world.characterization_digest_v0().expect("baseline digest");
        let baseline_food = world.food().cells().to_vec();
        let baseline_revision = world.config_revision();
        let baseline_audit = world.config_audit().to_vec();

        for value in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            let error = world
                .try_update_agent(agent, |data, runtime| {
                    data.heading = 0.75;
                    runtime.sensors[7] = value;
                })
                .expect_err("runtime non-finite value must reject the whole candidate");
            assert_non_finite_path(
                &error,
                &format!("agents[{}].runtime.sensors[7]", agent.raw()),
            );
            assert_eq!(
                world
                    .characterization_digest_v0()
                    .expect("unchanged agent digest"),
                baseline,
                "the finite scalar edit must roll back with the invalid runtime edit"
            );

            let error = world
                .try_update_food(|cells| {
                    cells[0] = 0.125;
                    cells[3] = value;
                })
                .expect_err("bulk food update must reject non-finite cell");
            assert_non_finite_path(&error, "food.cells[3]");
            assert_eq!(world.food().cells(), baseline_food);
            assert_eq!(world.config_revision(), baseline_revision);
            assert_eq!(world.config_audit(), baseline_audit);
        }
    }

    #[test]
    fn detached_food_and_dense_agent_boundaries_cover_empty_single_and_bulk_values() {
        let mut columns = AgentColumns::new();
        assert!(columns.is_empty());
        columns
            .try_push(AgentData::default())
            .expect("single finite row");
        columns
            .try_push(AgentData {
                position: Position::new(-0.0, f32::MIN_POSITIVE),
                ..AgentData::default()
            })
            .expect("bulk finite row");
        let before_len = columns.len();
        let error = columns
            .try_push(AgentData {
                color: [0.0, f32::INFINITY, 1.0],
                ..AgentData::default()
            })
            .expect_err("invalid append must reject before touching any column");
        assert_non_finite_path(&error, "agents[2].color[1]");
        assert_eq!(columns.len(), before_len);

        let mut food = FoodGrid::new(2, 2, -0.0).expect("finite initial field");
        food.try_replace_cells(vec![0.0, 0.25, 0.5, 1.0])
            .expect("finite bulk replacement");
        let before = food.cells().to_vec();
        let error = food
            .try_replace_cells(vec![0.0])
            .expect_err("short replacement must reject atomically");
        assert_eq!(error.path(), "food.cells");
        assert_eq!(food.cells(), before);
        let error = FoodGrid::new(1, 1, f32::NAN).expect_err("invalid single cell");
        assert!(
            matches!(&error, WorldStateError::InvalidState(_)),
            "expected typed state error, got {error}"
        );
        let WorldStateError::InvalidState(error) = error else {
            return;
        };
        assert_non_finite_path(&error, "food.initial");
    }

    #[test]
    fn public_dense_allocators_reject_unrepresentable_layouts_before_allocation_or_rng_use() {
        assert_dimension_overflow(
            FoodGrid::new(u32::MAX, u32::MAX, 0.0)
                .expect_err("oversized food layout must be rejected"),
            "food",
        );

        let mut rng = SmallRng::seed_from_u64(0xA110_CAFE);
        let mut untouched_rng = rng.clone();
        assert_dimension_overflow(
            TerrainLayer::generate(u32::MAX, u32::MAX, 1, &mut rng)
                .expect_err("oversized terrain layout must be rejected"),
            "terrain.tiles",
        );
        assert_eq!(
            rng.next_u64(),
            untouched_rng.next_u64(),
            "layout rejection must happen before terrain generation consumes RNG"
        );
    }

    #[test]
    fn blood_sensor_cone_uses_strict_legacy_half_fov_boundary() {
        const ANGLE_EPSILON: f32 = 1.0e-4;
        const DISTANCE_FACTOR: f32 = 0.75;
        const TARGET_HEALTH: f32 = 1.0;

        let just_inside = blood_sensor_contribution(
            BLOOD_HALF_FOV - ANGLE_EPSILON,
            DISTANCE_FACTOR,
            TARGET_HEALTH,
        );
        let expected_inside =
            (ANGLE_EPSILON / BLOOD_HALF_FOV) * DISTANCE_FACTOR * (1.0 - TARGET_HEALTH / 2.0);

        assert!(just_inside > 0.0);
        assert!((just_inside - expected_inside).abs() <= 1.0e-7);
        assert_eq!(
            blood_sensor_contribution(BLOOD_HALF_FOV, DISTANCE_FACTOR, TARGET_HEALTH),
            0.0,
            "the legacy `diff4 < PI38` boundary excludes an on-edge target"
        );
        assert_eq!(
            blood_sensor_contribution(
                BLOOD_HALF_FOV + ANGLE_EPSILON,
                DISTANCE_FACTOR,
                TARGET_HEALTH,
            ),
            0.0,
            "a target just outside the legacy cone must not contribute"
        );
    }

