    #[test]
    fn stage_brains_preserves_scalar_fallback_when_family_declines_batch() {
        let mut world = WorldState::new(ScriptBotsConfig {
            population_minimum: 0,
            ..ScriptBotsConfig::default()
        })
        .expect("batch fallback world");
        let scalar_probe = Arc::new(Mutex::new(Vec::new()));
        let declining_probe = Arc::new(Mutex::new(Vec::new()));
        let scalar_key = world
            .register_brain_family(
                "scalar-only",
                Box::new(FixtureBrainFamily::scalar_only(
                    "scalar-only",
                    Arc::clone(&scalar_probe),
                )),
            )
            .expect("scalar-only family");
        let declining_key = world
            .register_brain_family(
                "declining-batch",
                Box::new(FixtureBrainFamily::declining_batch(
                    "declining-batch",
                    Arc::clone(&declining_probe),
                )),
            )
            .expect("declining family");

        let agents = [
            spawn_fixture_protocol_agent(
                &mut world,
                scalar_key,
                "scalar-only",
                fixture_protocol_lane(1, 2, 1, 3, 4.0),
            ),
            spawn_fixture_protocol_agent(
                &mut world,
                scalar_key,
                "scalar-only",
                fixture_protocol_lane(2, 3, -2, 1, 2.0),
            ),
            spawn_fixture_protocol_agent(
                &mut world,
                declining_key,
                "declining-batch",
                fixture_protocol_lane(3, -1, 2, 5, 3.0),
            ),
            spawn_fixture_protocol_agent(
                &mut world,
                declining_key,
                "declining-batch",
                fixture_protocol_lane(4, 2, 0, -1, 5.0),
            ),
        ];

        world.stage_brains().expect("scalar fallback stage");
        assert!(scalar_probe.lock().expect("scalar probe").is_empty());
        assert_eq!(
            *declining_probe.lock().expect("declining probe"),
            vec![vec![-1, 2]],
            "Ok(None) must be observed before exact scalar fallback"
        );
        for (agent, expected) in agents.into_iter().zip([12.0_f32, 5.0, 4.0, 9.0]) {
            assert_eq!(
                world.agent_runtime(agent).expect("fallback result").outputs[0].to_bits(),
                expected.to_bits()
            );
        }
    }

    #[cfg(feature = "batch-brains")]
    #[test]
    fn stage_batch_and_scalar_paths_are_bit_identical() {
        struct MatchedBatchWorld {
            world: WorldState,
            agents: [AgentId; 4],
            probe: Arc<Mutex<Vec<Vec<i8>>>>,
        }

        fn build_world(batch_enabled: bool) -> MatchedBatchWorld {
            let mut world = WorldState::new(ScriptBotsConfig {
                population_minimum: 0,
                rng_seed: Some(0xB17B_17B1),
                ..ScriptBotsConfig::default()
            })
            .expect("matched batch world");
            let probe = Arc::new(Mutex::new(Vec::new()));
            let family = if batch_enabled {
                FixtureBrainFamily::with_batch_probe("batch-scalar-match", Arc::clone(&probe))
            } else {
                FixtureBrainFamily::scalar_only("batch-scalar-match", Arc::clone(&probe))
            };
            let key = world
                .register_brain_family("batch-scalar-match", Box::new(family))
                .expect("matched family");
            let agents = [
                fixture_protocol_lane(1, 2, 1, 3, 4.0),
                fixture_protocol_lane(2, 3, -2, 1, 2.0),
                fixture_protocol_lane(3, -1, 2, 5, 3.0),
                fixture_protocol_lane(4, 2, 0, -1, 5.0),
            ]
            .map(|lane| spawn_fixture_protocol_agent(&mut world, key, "batch-scalar-match", lane));
            MatchedBatchWorld {
                world,
                agents,
                probe,
            }
        }

        let MatchedBatchWorld {
            world: mut scalar,
            agents: scalar_agents,
            probe: scalar_probe,
        } = build_world(false);
        let MatchedBatchWorld {
            world: mut batch,
            agents: batch_agents,
            probe: batch_probe,
        } = build_world(true);
        scalar.stage_brains().expect("matched scalar stage");
        batch.stage_brains().expect("matched batch stage");
        assert!(
            scalar_probe
                .lock()
                .expect("matched scalar probe")
                .is_empty()
        );
        assert_eq!(
            *batch_probe.lock().expect("matched batch probe"),
            vec![vec![2, 3, -1, 2]]
        );
        for (scalar_agent, batch_agent) in scalar_agents.into_iter().zip(batch_agents) {
            assert_eq!(
                output_bits(
                    scalar
                        .agent_runtime(scalar_agent)
                        .expect("matched scalar result")
                        .outputs,
                ),
                output_bits(
                    batch
                        .agent_runtime(batch_agent)
                        .expect("matched batch result")
                        .outputs,
                )
            );
            assert_eq!(
                scalar
                    .agent_brain_evaluator_state(scalar_agent)
                    .expect("matched scalar checkpoint"),
                batch
                    .agent_brain_evaluator_state(batch_agent)
                    .expect("matched batch checkpoint")
            );
        }
        assert_eq!(
            scalar.world_digest_v1().expect("matched scalar digest"),
            batch.world_digest_v1().expect("matched batch digest")
        );
    }

    #[cfg(feature = "batch-brains")]
    #[test]
    fn stage_brains_rolls_back_partial_batch_failure_atomically() {
        let mut world = WorldState::new(ScriptBotsConfig {
            population_minimum: 0,
            ..ScriptBotsConfig::default()
        })
        .expect("batch rollback world");
        let probe = Arc::new(Mutex::new(Vec::new()));
        let key = world
            .register_brain_family(
                "batch-rollback",
                Box::new(FixtureBrainFamily::failing_batch_after(
                    "batch-rollback",
                    1,
                    Arc::clone(&probe),
                )),
            )
            .expect("rollback family");
        let first = spawn_fixture_protocol_agent(
            &mut world,
            key,
            "batch-rollback",
            fixture_protocol_lane(1, 2, 1, 3, 4.0),
        );
        let second = spawn_fixture_protocol_agent(
            &mut world,
            key,
            "batch-rollback",
            fixture_protocol_lane(2, 3, -2, 1, 2.0),
        );
        let before = [first, second].map(|agent| {
            world
                .agent_brain_evaluator_state(agent)
                .expect("pre-failure checkpoint")
                .expect("pre-failure protocol state")
        });
        for agent in [first, second] {
            world
                .agent_runtime_mut(agent)
                .expect("pre-failure runtime")
                .outputs = [9.0; OUTPUT_SIZE];
        }

        let error = world
            .stage_brains()
            .expect_err("partial batch mutation must fail the whole cohort");
        assert_eq!(error.kind(), "batch-rollback");
        assert!(error.to_string().contains("fixture batch failed at lane 1"));
        assert_eq!(*probe.lock().expect("rollback probe"), vec![vec![2, 3]]);
        for (lane, agent) in [first, second].into_iter().enumerate() {
            let runtime = world.agent_runtime(agent).expect("rolled-back runtime");
            assert_eq!(runtime.outputs, [0.0; OUTPUT_SIZE]);
            assert!(runtime.brain.is_bound());
            assert_eq!(
                world
                    .agent_brain_evaluator_state(agent)
                    .expect("post-failure checkpoint")
                    .expect("post-failure protocol state"),
                before[lane]
            );
        }
    }

