    #[derive(Clone, Default)]
    struct SpyPersistence {
        logs: Arc<Mutex<Vec<PersistenceBatch>>>,
    }

    impl WorldPersistence for SpyPersistence {
        fn on_tick(&mut self, payload: &PersistenceBatch) -> Result<(), PersistenceAdmissionError> {
            self.logs.lock().unwrap().push(payload.clone());
            Ok(())
        }
    }

    struct RejectOncePersistence {
        logs: Arc<Mutex<Vec<PersistenceBatch>>>,
        reject_next: bool,
    }

    impl WorldPersistence for RejectOncePersistence {
        fn on_tick(&mut self, payload: &PersistenceBatch) -> Result<(), PersistenceAdmissionError> {
            self.logs.lock().unwrap().push(payload.clone());
            if self.reject_next {
                self.reject_next = false;
                Err(PersistenceAdmissionError::new(
                    payload.summary.tick.0,
                    "injected definite non-admission",
                ))
            } else {
                Ok(())
            }
        }
    }

    struct DelayedSpyPersistence {
        logs: Arc<Mutex<Vec<PersistenceBatch>>>,
        delay: Duration,
    }

    impl WorldPersistence for DelayedSpyPersistence {
        fn on_tick(&mut self, payload: &PersistenceBatch) -> Result<(), PersistenceAdmissionError> {
            std::thread::sleep(self.delay);
            self.logs.lock().unwrap().push(payload.clone());
            Ok(())
        }
    }

    fn world_with_session(
        config: ScriptBotsConfig,
        sink: impl WorldPersistence + 'static,
    ) -> (WorldState, PersistenceAdmissionSession) {
        WorldState::with_persistence(config, Box::new(sink)).expect("world and persistence session")
    }

    fn ready_batch_arc(projection: &PersistenceProjection) -> Arc<PersistenceBatch> {
        assert_eq!(projection.status(), PersistenceProjectionStatus::Ready);
        Arc::clone(
            projection
                .batch
                .as_ref()
                .expect("ready projection owns an immutable batch"),
        )
    }

    fn assert_same_staged_batch(
        session: &PersistenceAdmissionSession,
        projected: &Arc<PersistenceBatch>,
    ) {
        let retained = &session
            .pending
            .as_ref()
            .expect("session staged the ready projection")
            .batch;
        assert!(
            Arc::ptr_eq(projected, retained),
            "session must share the projection's exact Arc allocation"
        );
    }

    fn assert_persistence_batches_exact(left: &PersistenceBatch, right: &PersistenceBatch) {
        assert_eq!(left.summary, right.summary);
        assert_eq!(left.epoch, right.epoch);
        assert_eq!(left.closed, right.closed);
        assert_eq!(left.metrics, right.metrics);
        assert_eq!(left.events, right.events);
        assert_eq!(left.births, right.births);
        assert_eq!(left.deaths, right.deaths);
        assert_eq!(left.replay_events, right.replay_events);
        assert_eq!(
            postcard::to_allocvec(&left.agents).expect("encode left agents"),
            postcard::to_allocvec(&right.agents).expect("encode right agents")
        );
    }

    fn sealed_agent_boundary(tick: u64) -> ScientificStateError {
        ScientificStateError::PersistenceBoundarySealed {
            path: "agent".to_owned(),
            tick,
        }
    }

    fn unresolved_agent_boundary(tick: u64) -> ScientificStateError {
        ScientificStateError::PersistenceBoundaryUnresolved {
            path: "agent".to_owned(),
            tick,
        }
    }

    #[test]
    fn prepared_persistence_is_inert_until_the_exact_batch_is_admitted() {
        let logs = Arc::new(Mutex::new(Vec::new()));
        let persistence = RejectOncePersistence {
            logs: Arc::clone(&logs),
            reject_next: true,
        };
        let (mut world, mut session) = world_with_session(
            ScriptBotsConfig {
                persistence_interval: 1,
                population_minimum: 0,
                population_spawn_interval: 0,
                closed: true,
                rng_seed: Some(0xA11D_5EED),
                ..ScriptBotsConfig::default()
            },
            persistence,
        );
        let live_agent = world
            .try_spawn_agent(sample_agent(7))
            .expect("seed live projection agent");
        let live_uid = world.agent_uid(live_agent).expect("live uid");
        world.pending_birth_records.clear();
        world.pending_lifecycle_birth_metrics.clear();
        let birth = lifecycle_birth(1);
        let death = lifecycle_death(1);
        world.pending_birth_records.push(birth.clone());
        world.pending_death_records.push(death.clone());
        world.pending_lifecycle_birth_metrics.push(birth);
        world.pending_lifecycle_death_metrics.push(death);
        world.last_births = 1;
        world.last_deaths = 1;
        world.combat_spike_attempts = 2;
        world.combat_spike_hits = 1;
        world.carcass_health_distributed = 3.5;
        world.carcass_reproduction_bonus = 1.25;
        world.replay_events.push(replay_marker(0.25));
        let runtime_tail = PersistenceRuntimeTail::capture(
            live_uid,
            world.runtime.get(live_agent).expect("live runtime"),
        );
        world
            .pending_persistence_runtime_tail
            .insert(live_agent, runtime_tail);
        world.epoch = 4;
        world.stage_accumulate_tick_events();
        world.stage_record_history(Tick(1));

        let projection = world.prepare_persistence(Tick(1), false);
        assert!(logs.lock().unwrap().is_empty());
        assert_eq!(projection.status(), PersistenceProjectionStatus::Ready);
        let batch = ready_batch_arc(&projection);
        assert_eq!(batch.summary.tick, Tick(1));
        assert_eq!(batch.summary.births, 1);
        assert_eq!(batch.summary.deaths, 1);
        assert_eq!(batch.epoch, 4);
        assert!(batch.closed);
        assert_eq!(batch.agents.len(), 1);
        assert_eq!(batch.births.len(), 1);
        assert_eq!(batch.deaths.len(), 1);
        assert_eq!(batch.replay_events.len(), 1);
        assert!(
            batch
                .metrics
                .iter()
                .any(|metric| metric.name == "carcass_health_distributed")
        );
        assert!(
            batch
                .metrics
                .iter()
                .any(|metric| metric.name == "carcass_reproduction_bonus")
        );
        assert!(world.pending_birth_records.is_empty());
        assert!(world.pending_death_records.is_empty());
        assert!(world.pending_lifecycle_birth_metrics.is_empty());
        assert!(world.pending_lifecycle_death_metrics.is_empty());
        assert!(world.replay_events.is_empty());
        assert!(world.pending_persistence_runtime_tail.is_empty());
        assert_eq!(world.pending_birth_events, 0);
        assert_eq!(world.pending_death_events, 0);
        assert_eq!(world.pending_spike_attempt_events, 0);
        assert_eq!(world.pending_spike_hit_events, 0);
        assert_eq!(world.carcass_health_distributed, 0.0);
        assert_eq!(world.carcass_reproduction_bonus, 0.0);

        let expected = Arc::clone(&batch);
        let digest_before_admission = world
            .world_digest_v1_inner(false)
            .expect("prepared scientific lanes");
        session.stage_projection(&mut world, &projection);
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Pending { tick: Tick(1) }
        );
        assert_same_staged_batch(&session, &batch);
        assert!(logs.lock().unwrap().is_empty());

        let rejection = session
            .admit_pending(&mut world)
            .expect_err("injected admission rejection");
        assert!(
            matches!(&rejection, PersistenceSessionError::Admission(_)),
            "expected typed sink rejection"
        );
        let PersistenceSessionError::Admission(rejection) = rejection else {
            return;
        };
        assert_eq!(rejection.state(), PersistenceAdmissionState::NotAdmitted);
        assert_eq!(
            world
                .world_digest_v1_inner(false)
                .expect("rejected scientific lanes"),
            digest_before_admission
        );
        assert_eq!(logs.lock().unwrap().len(), 1);
        assert_eq!(session.fault(), Some(&rejection));
        assert_same_staged_batch(&session, &expected);
        let retained = session.pending_batch().expect("exact retained batch");
        assert_persistence_batches_exact(retained, expected.as_ref());
        assert_eq!(
            postcard::to_allocvec(&retained.agents).expect("encode retained agents"),
            postcard::to_allocvec(&expected.agents).expect("encode projected agents")
        );

        assert!(
            session
                .retry_pending(&mut world)
                .expect("exact retained batch retry")
        );
        assert!(!session.has_pending_batch());
        assert!(session.fault().is_none());
        assert_eq!(session.last_admitted_tick(), Some(Tick(1)));
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Sealed { tick: Tick(1) }
        );
        let attempts = logs.lock().unwrap();
        assert_eq!(attempts.len(), 2);
        assert_persistence_batches_exact(&attempts[0], &attempts[1]);
    }

    #[test]
    fn step_outcome_is_sink_inert_and_carries_the_full_completed_boundary() {
        let mut config = quiet_trace_config(0x57E0_0A7C, 1);
        config.closed = false;
        config.population_minimum = 2;
        config.spike_radius = 20.0;
        config.spike_damage = 0.5;
        config.spike_energy_cost = 0.0;
        config.spike_min_length = 0.1;
        config.spike_alignment_cosine = 0.1;
        config.spike_speed_damage_bonus = 0.0;
        config.spike_length_damage_bonus = 0.0;

        let logs = Arc::new(Mutex::new(Vec::new()));
        let persistence = RejectOncePersistence {
            logs: Arc::clone(&logs),
            reject_next: true,
        };
        let (mut world, mut session) = world_with_session(config, persistence);
        let mut updated = world.config().clone();
        updated.chart_flush_interval = 1;
        world
            .apply_config_update(updated)
            .expect("harmless outcome revision");

        let attacker = world.spawn_agent(sample_agent(0));
        let victim = world.spawn_agent(sample_agent(1));
        let victim_uid = world.agent_uid(victim).expect("victim uid");
        let attacker_brain = world
            .brain_registry_mut()
            .expect("outcome aggressor registry mutation")
            .register("test.outcome-aggressor", |_rng| {
                Ok(Box::new(LedgerAggressorBrain))
            });
        let idle_brain = world
            .brain_registry_mut()
            .expect("outcome idle registry mutation")
            .register("test.outcome-idle", |_rng| Ok(Box::new(LedgerIdleBrain)));
        assert!(
            world
                .bind_agent_brain(attacker, attacker_brain)
                .expect("outcome aggressor brain")
        );
        assert!(
            world
                .bind_agent_brain(victim, idle_brain)
                .expect("outcome idle brain")
        );
        {
            let attacker_index = world.agents.index_of(attacker).expect("attacker index");
            let victim_index = world.agents.index_of(victim).expect("victim index");
            let columns = world.agents.columns_mut();
            columns.positions_mut()[attacker_index] = Position::new(10.0, 10.0);
            columns.positions_mut()[victim_index] = Position::new(15.0, 10.0);
            columns.headings_mut()[attacker_index] = 0.0;
            columns.headings_mut()[victim_index] = 0.0;
            columns.health_mut()[attacker_index] = 1.0;
            columns.health_mut()[victim_index] = 0.08;
            columns.spike_lengths_mut()[attacker_index] = 1.0;
        }
        {
            let runtime = world
                .agent_runtime_mut(attacker)
                .expect("outcome attacker runtime");
            runtime.energy = 1.0;
            runtime.herbivore_tendency = 0.0;
        }
        {
            let runtime = world
                .agent_runtime_mut(victim)
                .expect("outcome victim runtime");
            runtime.energy = 0.2;
            runtime.herbivore_tendency = 1.0;
        }
        world.set_resource_ledger_enabled(true);

        let StepCompletion { outcome, fault } = session
            .step_outcome(&mut world)
            .expect("completed outcome step");

        assert!(fault.is_none());
        assert!(logs.lock().unwrap().is_empty());
        assert_eq!(world.tick(), Tick(1));
        assert_eq!(outcome.events.tick, Tick(1));
        assert!(outcome.events.charts_flushed);
        assert_eq!(
            &outcome.summary,
            world.history().next_back().expect("completed summary")
        );
        assert_eq!(outcome.summary.agent_count, 2);
        assert_eq!(outcome.summary.births, 0);
        assert_eq!(outcome.summary.deaths, 1);
        assert_eq!(outcome.summary.spike_hits, 1);
        assert_eq!(outcome.births.len(), 1);
        assert!(
            outcome
                .births
                .iter()
                .all(|record| { record.tick == Tick(1) && record.origin == BirthOrigin::Injected })
        );
        assert_eq!(outcome.deaths.len(), 1);
        assert_eq!(outcome.deaths[0].tick, Tick(1));
        assert_eq!(outcome.deaths[0].agent_uid, victim_uid);
        assert_eq!(
            outcome.combat,
            TickCombatSummary {
                spike_attempts: 1,
                spike_hits: 1,
            }
        );
        assert_eq!(outcome.config_revision, 1);
        assert_eq!(outcome.config_revision, world.config_revision());
        assert_eq!(
            outcome.resource_tick.as_ref(),
            world.resource_ledger().latest.as_ref()
        );
        assert_latest_ledger_reconciles(&world);
        assert_eq!(
            outcome.persistence.status(),
            PersistenceProjectionStatus::Ready
        );
        let expected = ready_batch_arc(&outcome.persistence);
        assert_same_staged_batch(&session, &expected);
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Pending { tick: Tick(1) }
        );
        {
            let batch = outcome.persistence.batch().expect("ready exact batch");
            assert_eq!(batch.summary, outcome.summary);
            assert_eq!(batch.deaths, outcome.deaths);
            let current_births = batch
                .births
                .iter()
                .filter(|record| record.tick == Tick(1))
                .cloned()
                .collect::<Vec<_>>();
            assert_eq!(current_births, outcome.births);
            assert_eq!(batch.births.len(), outcome.births.len() + 2);
        }
        assert_eq!(session.last_admitted_tick(), None);
        assert!(session.has_pending_batch());
        assert!(session.fault().is_none());

        let science_before_admission = world
            .world_digest_v1_inner(false)
            .expect("completed outcome science lanes");
        let tick_before_admission = world.tick();
        let history_before_admission = world.history().cloned().collect::<Vec<_>>();
        let resource_before_admission = world.resource_ledger().clone();
        let config_revision_before_admission = world.config_revision();
        let last_spike_hits_before_admission = world.last_spike_hits();
        let last_max_age_before_admission = world.last_max_age();
        let rejection = session
            .admit_pending(&mut world)
            .expect_err("injected downstream rejection");
        assert!(
            matches!(&rejection, PersistenceSessionError::Admission(_)),
            "expected typed sink rejection"
        );
        let PersistenceSessionError::Admission(rejection) = rejection else {
            return;
        };
        assert_eq!(rejection.state(), PersistenceAdmissionState::NotAdmitted);
        assert_eq!(logs.lock().unwrap().len(), 1);
        assert_eq!(session.fault(), Some(&rejection));
        assert!(session.has_pending_batch());
        assert_same_staged_batch(&session, &expected);
        assert_eq!(
            world
                .world_digest_v1_inner(false)
                .expect("science lanes after downstream rejection"),
            science_before_admission
        );
        assert_eq!(world.tick(), tick_before_admission);
        assert_eq!(
            world.history().cloned().collect::<Vec<_>>(),
            history_before_admission
        );
        assert_eq!(world.resource_ledger(), &resource_before_admission);
        assert_eq!(world.config_revision(), config_revision_before_admission);
        assert_eq!(world.last_spike_hits(), last_spike_hits_before_admission);
        assert_eq!(world.last_max_age(), last_max_age_before_admission);
        let retained = session
            .pending_batch()
            .expect("exact outcome batch retained");
        assert_persistence_batches_exact(retained, expected.as_ref());
    }

    #[test]
    fn outcome_step_variants_never_admit_the_installed_sink() {
        fn outcome_world(
            seed: u64,
        ) -> (
            WorldState,
            PersistenceAdmissionSession,
            Arc<Mutex<Vec<PersistenceBatch>>>,
        ) {
            let spy = SpyPersistence::default();
            let logs = Arc::clone(&spy.logs);
            let (world, session) = world_with_session(quiet_trace_config(seed, 1), spy);
            (world, session, logs)
        }

        let (mut plain, mut plain_session, plain_logs) = outcome_world(0x0A71_0001);
        let plain_completion = plain_session
            .step_outcome(&mut plain)
            .expect("plain outcome");
        assert_eq!(
            plain_completion.outcome.persistence.status(),
            PersistenceProjectionStatus::Ready
        );
        let plain_batch = ready_batch_arc(&plain_completion.outcome.persistence);
        assert_same_staged_batch(&plain_session, &plain_batch);
        assert!(plain_logs.lock().unwrap().is_empty());

        let (mut profiled, mut profiled_session, profiled_logs) = outcome_world(0x0A71_0002);
        let mut step_profiler = WorldStepProfiler::default();
        let profiled_completion = profiled_session
            .step_profiled_outcome(&mut profiled, &mut step_profiler)
            .expect("profiled outcome");
        assert_eq!(
            profiled_completion.outcome.persistence.status(),
            PersistenceProjectionStatus::Ready
        );
        let profiled_batch = ready_batch_arc(&profiled_completion.outcome.persistence);
        assert_same_staged_batch(&profiled_session, &profiled_batch);
        assert!(profiled_logs.lock().unwrap().is_empty());
        assert_eq!(
            step_profiler.latest().expect("core profile").schema,
            WORLD_STEP_OUTCOME_PROFILE_SCHEMA
        );

        let (mut traced, mut traced_session, traced_logs) = outcome_world(0x0A71_0003);
        let mut step_tracer = WorldStepTracer::default();
        let traced_completion = traced_session
            .step_traced_outcome(&mut traced, &mut step_tracer)
            .expect("traced outcome");
        assert_eq!(
            traced_completion.outcome.persistence.status(),
            PersistenceProjectionStatus::Ready
        );
        let traced_batch = ready_batch_arc(&traced_completion.outcome.persistence);
        assert_same_staged_batch(&traced_session, &traced_batch);
        assert!(traced_logs.lock().unwrap().is_empty());
        step_tracer
            .latest()
            .expect("outcome trace")
            .validate_contract()
            .expect("valid outcome trace");

        let legacy_delay = Duration::from_millis(10);
        let legacy_logs = Arc::new(Mutex::new(Vec::new()));
        let legacy_persistence = DelayedSpyPersistence {
            logs: Arc::clone(&legacy_logs),
            delay: legacy_delay,
        };
        let (mut legacy, mut legacy_session) =
            world_with_session(quiet_trace_config(0x0A71_0004, 1), legacy_persistence);
        let mut legacy_profiler = WorldStepProfiler::default();
        legacy_session
            .step_profiled(&mut legacy, &mut legacy_profiler)
            .expect("legacy profiled step");
        assert_eq!(legacy_logs.lock().unwrap().len(), 1);
        let legacy_profile = legacy_profiler.latest().expect("legacy profile");
        assert_eq!(legacy_profile.schema, WORLD_STEP_PROFILE_SCHEMA);
        assert!(
            legacy_profile
                .elapsed_ns(WorldStepStage::Persistence)
                .expect("legacy persistence timing")
                >= duration_ns(legacy_delay),
            "legacy v2 persistence timing must include downstream admission"
        );
        assert!(
            legacy_profile.total_ns
                >= legacy_profile
                    .elapsed_ns(WorldStepStage::Persistence)
                    .expect("legacy persistence timing")
        );
    }

    #[test]
    fn legacy_v2_profile_includes_staging_and_result_tail_without_contaminating_v3() {
        const STAGING_NS: u64 = 1_000_000_000_000;
        const RESULT_NS: u64 = 2_000_000_000_000;

        {
            let spy = SpyPersistence::default();
            let (mut world, mut session) =
                world_with_session(quiet_trace_config(0x0A71_00A3, 1), spy);
            let mut profiler = WorldStepProfiler::default();
            profiler.set_tail_clock(Box::new(SyntheticTailClock::new(STAGING_NS, RESULT_NS)));

            let completion = session
                .step_profiled_outcome(&mut world, &mut profiler)
                .expect("v3 profiled outcome");
            let profile = profiler.latest().expect("v3 profile");
            assert_eq!(profile.schema, WORLD_STEP_OUTCOME_PROFILE_SCHEMA);
            assert_eq!(
                profiler.synthetic_tail_ns(),
                0,
                "the core-only v3 outcome boundary must not enter either legacy tail"
            );
            let projected = ready_batch_arc(&completion.outcome.persistence);
            assert_same_staged_batch(&session, &projected);
        }

        let spy = SpyPersistence::default();
        let (mut world, mut session) = world_with_session(quiet_trace_config(0x0A71_00A2, 1), spy);
        let mut profiler = WorldStepProfiler::default();
        profiler.set_tail_clock(Box::new(SyntheticTailClock::new(STAGING_NS, RESULT_NS)));

        session
            .step_profiled(&mut world, &mut profiler)
            .expect("legacy v2 profiled step");
        let profile = profiler.latest().expect("legacy v2 profile");
        let persistence_ns = profile
            .elapsed_ns(WorldStepStage::Persistence)
            .expect("legacy persistence timing");
        assert_eq!(profile.schema, WORLD_STEP_PROFILE_SCHEMA);
        assert_eq!(
            profiler.synthetic_tail_ns(),
            STAGING_NS.saturating_add(RESULT_NS)
        );
        assert!(
            persistence_ns >= STAGING_NS,
            "legacy persistence timing must start before session staging"
        );
        assert!(
            profile.total_ns >= STAGING_NS.saturating_add(RESULT_NS),
            "legacy total must include both downstream tail segments"
        );
        assert!(
            profile.total_ns.saturating_sub(persistence_ns) >= RESULT_NS,
            "legacy total must end only after typed result composition"
        );
    }

    #[test]
    fn step_outcomes_are_tick_local_while_ready_persistence_accumulates_cadence() {
        let mut config = quiet_trace_config(0x0A7C_CADE, 2);
        config.aging_tick_interval = 1;
        config.aging_health_decay_start = 0;
        config.aging_health_decay_rate = 0.1;
        config.aging_health_decay_max = 0.1;
        let (mut world, mut session) = world_with_session(config, NullPersistence);
        let first = world.spawn_agent(sample_agent(0));
        let second = world.spawn_agent(sample_agent(1));
        let first_uid = world.agent_uid(first).expect("first cadence uid");
        let second_uid = world.agent_uid(second).expect("second cadence uid");
        {
            let first_index = world.agents.index_of(first).expect("first cadence index");
            let second_index = world.agents.index_of(second).expect("second cadence index");
            let health = world.agents.columns_mut().health_mut();
            health[first_index] = 0.05;
            health[second_index] = 0.15;
        }

        let first_completion = session
            .step_outcome(&mut world)
            .expect("first cadence outcome");
        assert!(first_completion.fault.is_none());
        assert_eq!(first_completion.outcome.summary.deaths, 1);
        assert_eq!(first_completion.outcome.deaths.len(), 1);
        assert_eq!(first_completion.outcome.deaths[0].agent_uid, first_uid);
        assert_eq!(
            first_completion.outcome.persistence.status(),
            PersistenceProjectionStatus::Deferred
        );
        assert!(first_completion.outcome.persistence.batch().is_none());
        assert!(!session.has_pending_batch());
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Open { tick: Tick(1) }
        );

        let second_completion = session
            .step_outcome(&mut world)
            .expect("second cadence outcome");
        assert!(second_completion.fault.is_none());
        assert_eq!(second_completion.outcome.summary.deaths, 1);
        assert_eq!(second_completion.outcome.deaths.len(), 1);
        assert_eq!(second_completion.outcome.deaths[0].agent_uid, second_uid);
        assert_eq!(
            second_completion.outcome.persistence.status(),
            PersistenceProjectionStatus::Ready
        );
        let projected_batch = ready_batch_arc(&second_completion.outcome.persistence);
        assert_same_staged_batch(&session, &projected_batch);
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Pending { tick: Tick(2) }
        );
        let batch = projected_batch.as_ref();
        assert_eq!(batch.summary.tick, Tick(2));
        assert_eq!(batch.summary.deaths, 2);
        assert_eq!(batch.deaths.len(), 2);
        assert_eq!(
            batch
                .deaths
                .iter()
                .map(|death| death.agent_uid)
                .collect::<Vec<_>>(),
            vec![first_uid, second_uid]
        );
        assert_ne!(batch.summary, second_completion.outcome.summary);
    }

    #[test]
    fn disabled_resource_ledger_does_not_republish_a_stale_tick_in_outcome() {
        let mut world =
            WorldState::new(quiet_trace_config(0x0A7C_1ED6, 0)).expect("outcome ledger world");
        world.set_resource_ledger_enabled(true);
        let first = world.step_outcome().expect("instrumented outcome");
        assert_eq!(
            first
                .outcome
                .resource_tick
                .as_ref()
                .map(|report| report.tick),
            Some(Tick(1))
        );

        world.set_resource_ledger_enabled(false);
        let second = world.step_outcome().expect("uninstrumented outcome");
        assert!(second.outcome.resource_tick.is_none());
        assert_eq!(
            world
                .resource_ledger()
                .latest
                .as_ref()
                .map(|report| report.tick),
            Some(Tick(1)),
            "the retained diagnostic report must not masquerade as tick two"
        );
    }

    #[test]
    // bd-tqpj: the spy-log mutex guard must stay held across this test's batch assertions; drop order is semantic.
    #[allow(clippy::significant_drop_tightening)]
    fn tick_zero_seed_finalizes_exactly_once() {
        let config = ScriptBotsConfig {
            persistence_interval: 3,
            population_minimum: 0,
            population_spawn_interval: 0,
            rng_seed: Some(0x71C0_5EED),
            ..ScriptBotsConfig::default()
        };
        let spy = SpyPersistence::default();
        let logs = Arc::clone(&spy.logs);
        let (mut world, mut session) = world_with_session(config, spy);
        let seeded = world
            .try_spawn_agent(sample_agent(2))
            .expect("tick-zero seed");
        let seeded_uid = world.agent_uid(seeded).expect("seeded uid");

        assert!(session.finalize(&mut world).expect("first finalization"));
        assert!(
            !session
                .finalize(&mut world)
                .expect("idempotent second finalization")
        );

        assert!(world.pending_birth_records.is_empty());
        assert_eq!(session.last_admitted_tick(), Some(Tick::zero()));
        assert!(!session.has_pending_batch());
        assert!(session.fault().is_none());
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Sealed { tick: Tick::zero() }
        );
        let entries = logs.lock().unwrap();
        assert_eq!(entries.len(), 1);
        let batch = &entries[0];
        assert_eq!(batch.summary.tick, Tick::zero());
        assert_eq!(batch.summary.births, 0);
        assert_eq!(batch.agents.len(), 1);
        assert_eq!(batch.births.len(), 1);
        assert_eq!(batch.births[0].tick, Tick::zero());
        assert_eq!(batch.births[0].agent_uid, seeded_uid);
        assert_eq!(batch.births[0].origin, BirthOrigin::Seeded);
    }

    #[test]
    fn empty_tick_zero_remains_unfinalized() {
        let config = ScriptBotsConfig {
            persistence_interval: 3,
            population_minimum: 0,
            population_spawn_interval: 0,
            rng_seed: Some(0xE0_71C0),
            ..ScriptBotsConfig::default()
        };
        let spy = SpyPersistence::default();
        let logs = Arc::clone(&spy.logs);
        let (mut world, mut session) = world_with_session(config, spy);

        assert!(!session.finalize(&mut world).expect("empty finalization"));
        assert!(
            !session
                .finalize(&mut world)
                .expect("repeated empty finalization")
        );
        assert_eq!(world.validate_external_arrival_boundary(), Ok(()));
        assert_eq!(session.last_admitted_tick(), None);
        assert!(!session.has_pending_batch());
        assert!(session.fault().is_none());
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Open { tick: Tick::zero() }
        );
        assert!(logs.lock().unwrap().is_empty());
    }

    #[test]
    fn sealed_tick_zero_rejects_every_public_ingress_before_callback_or_mutation() {
        let config = ScriptBotsConfig {
            persistence_interval: 1,
            population_minimum: 0,
            population_spawn_interval: 0,
            rng_seed: Some(0x5EA1_ED00),
            ..ScriptBotsConfig::default()
        };
        let spy = SpyPersistence::default();
        let logs = Arc::clone(&spy.logs);
        let (mut world, mut session) = world_with_session(config, spy);
        world
            .try_spawn_agent(sample_agent(1))
            .expect("initial tick-zero seed");
        assert!(session.finalize(&mut world).expect("tick-zero admission"));
        assert_eq!(session.last_admitted_tick(), Some(Tick::zero()));
        assert_eq!(
            world.persistence_boundary,
            PersistenceBoundaryStatus::Sealed { tick: Tick::zero() }
        );

        // The admitted marker is historical: temporarily disabling persistence
        // must not reopen this already-admitted tick to a second origin row.
        let mut disabled = world.config().clone();
        disabled.persistence_interval = 0;
        world
            .apply_config_update(disabled)
            .expect("disable persistence after admission");

        let expected = sealed_agent_boundary(0);
        assert_eq!(
            world.validate_external_arrival_boundary(),
            Err(expected.clone())
        );
        let before_rng = world.random_streams_checkpoint();
        let before_identity = world.identity_sequence_state();
        let before_agent_count = world.agent_count();
        let before_births = world.pending_birth_records.clone();
        let before_lifecycle_births = world.pending_lifecycle_birth_metrics.clone();
        let before_deaths = world.pending_death_records.clone();
        let before_replay = world.replay_events.clone();
        let before_digest = world
            .characterization_digest_v0()
            .expect("pre-rejection digest");
        let before_log_count = logs.lock().unwrap().len();
        let callback_calls = Cell::new(0usize);

        let invalid_seed = AgentData {
            position: Position::new(f32::NAN, 0.0),
            ..sample_agent(2)
        };
        assert_eq!(
            world.try_spawn_agent_with(invalid_seed, |_| {
                callback_calls.set(callback_calls.get() + 1);
            }),
            Err(expected.clone())
        );
        let invalid_injection = AgentData {
            position: Position::new(f32::NAN, 0.0),
            ..sample_agent(3)
        };
        assert_eq!(
            world.try_inject_agent_with(invalid_injection, |_| {
                callback_calls.set(callback_calls.get() + 1);
            }),
            Err(expected.clone())
        );

        assert_eq!(callback_calls.get(), 0);
        assert_eq!(world.random_streams_checkpoint(), before_rng);
        assert_eq!(world.identity_sequence_state(), before_identity);
        assert_eq!(world.agent_count(), before_agent_count);
        assert_eq!(world.pending_birth_records, before_births);
        assert_eq!(
            world.pending_lifecycle_birth_metrics,
            before_lifecycle_births
        );
        assert_eq!(world.pending_death_records, before_deaths);
        assert_eq!(world.replay_events, before_replay);
        assert_eq!(
            world
                .characterization_digest_v0()
                .expect("post-rejection digest"),
            before_digest
        );
        assert_eq!(logs.lock().unwrap().len(), before_log_count);

        let mut reenabled = world.config().clone();
        reenabled.persistence_interval = 1;
        world
            .apply_config_update(reenabled)
            .expect("re-enable persistence after admitted marker");
        assert!(
            !session
                .finalize(&mut world)
                .expect("historical admission remains final")
        );
        assert_eq!(
            world.validate_external_arrival_boundary(),
            Err(expected.clone())
        );
        let reenabled_rng = world.random_streams_checkpoint();
        let reenabled_identity = world.identity_sequence_state();
        assert_eq!(
            world.try_inject_agent_with(sample_agent(4), |_| {
                callback_calls.set(callback_calls.get() + 1);
            }),
            Err(expected)
        );
        assert_eq!(callback_calls.get(), 0);
        assert_eq!(world.random_streams_checkpoint(), reenabled_rng);
        assert_eq!(world.identity_sequence_state(), reenabled_identity);
        assert_eq!(logs.lock().unwrap().len(), 1);
    }

