    #[test]
    fn flow_class_labels_are_pinned_and_load_bearing() {
        // bd-16g.11.1 NEGATIVE 2 (adapted to the landed type system): the
        // external/internal/sink labels are what stops sunlight regrowth from
        // looking like a conservation violation — or a real leak hiding inside
        // it. The reconciliation math is label-agnostic, so the label's teeth
        // are this table: every reclassification shows up here in a diff.
        use ResourceFlowKind as K;
        let expected = [
            (K::ScenarioIntervention, FlowClass::ExternalInput),
            (K::FoodDynamics, FlowClass::ExternalInput),
            (K::Aging, FlowClass::Sink),
            (K::BasalMetabolism, FlowClass::Sink),
            (K::Movement, FlowClass::Sink),
            (K::MetabolismRamp, FlowClass::Sink),
            (K::Boost, FlowClass::Sink),
            (K::Topography, FlowClass::Sink),
            (K::TemperatureStress, FlowClass::Sink),
            (K::GroundFoodConversion, FlowClass::InternalTransfer),
            (K::EnergySharing, FlowClass::InternalTransfer),
            (K::Combat, FlowClass::Sink),
            (K::CarcassReward, FlowClass::ExternalInput),
            (K::DeathRemoval, FlowClass::Sink),
            (K::ReproductionAllocation, FlowClass::InternalTransfer),
            (K::PopulationInjection, FlowClass::ExternalInput),
            (K::CapacityRejection, FlowClass::Sink),
        ];
        assert_eq!(expected.len(), RESOURCE_FLOW_KINDS.len());
        for (index, kind) in RESOURCE_FLOW_KINDS.into_iter().enumerate() {
            assert_eq!(kind, expected[index].0, "kind table order changed");
            assert_eq!(
                kind.flow_class(),
                expected[index].1,
                "{kind:?} reclassified — the external/internal/sink labels are load-bearing"
            );
        }
        // The specific mislabel the bead calls out: sunlight regrowth must read
        // as an EXTERNAL input, never an internal transfer.
        assert_eq!(K::FoodDynamics.flow_class(), FlowClass::ExternalInput);
    }

    #[test]
    fn a_cap_spill_tick_posts_the_spill_as_capacity_rejection_activity() {
        // bd-16g.11.1 fixture (b): an agent at energy 1.99 eating a 0.5 gain is
        // credited exactly 0.01; the 0.49 the cap destroys is measured as
        // CapacityRejection ACTIVITY (the delta stays reconciliation-clean —
        // the clamp already shaped the credited stock), and the books balance.
        let mut world = WorldState::new(ScriptBotsConfig {
            world_width: 200,
            world_height: 200,
            food_cell_size: 20,
            initial_food: 0.9,
            food_max: 1.0,
            food_intake_rate: 1.0,
            food_waste_rate: 0.0,
            food_transfer_rate: 0.0,
            metabolism_drain: 0.0,
            movement_drain: 0.0,
            temperature_discomfort_rate: 0.0,
            reproduction_energy_threshold: 0.0,
            rng_seed: Some(0xCA9_5A11),
            ..ScriptBotsConfig::default()
        })
        .expect("world");
        let agent = world
            .try_spawn_agent(AgentData {
                position: Position::new(100.0, 100.0),
                ..AgentData::default()
            })
            .expect("spawn eater");
        world
            .try_update_agent_runtime(agent, |runtime| {
                runtime.energy = 1.99;
                runtime.herbivore_tendency = 1.0;
            })
            .expect("near-full energy");
        world.set_resource_ledger_enabled(true);
        world.step().expect("cap-spill tick");

        let latest = world
            .resource_ledger()
            .latest
            .clone()
            .expect("ledger recorded the tick");
        assert!(
            latest.reconciliation.reconciled,
            "cap-spill ticks must reconcile: {:?}",
            latest.reconciliation
        );
        let rejection = &latest.flows[ResourceFlowKind::CapacityRejection.index()];
        assert!(
            rejection.activity.energy > 0.4,
            "the destroyed 0.49 must be measured, not swallowed: {:?}",
            rejection.activity
        );
        // The credited stock changed by the clamped 0.01, not the requested 0.5.
        let energy_after = world.agent_runtime(agent).expect("runtime").energy;
        assert!(
            (energy_after - 2.0).abs() < 1e-6,
            "energy clamps at the cap: {energy_after}"
        );
    }

    #[test]
    fn seeded_runs_satisfy_the_class_signed_conservation_identity() {
        // bd-16g.11.1 property test: over seeded runs the books must close per
        // stock — the sum of every category's cumulative delta equals the
        // observed stock change within the derived tolerance. With the
        // flow_class table this decomposes as external_in - sinks +
        // internal_net == delta(stock), which is the identity that makes "do
        // the joules add up?" a number instead of a rumour.
        let configs = [
            ("baseline", ScriptBotsConfig::default(), 500_u64),
            (
                "tiny world, long run",
                ScriptBotsConfig {
                    world_width: 100,
                    world_height: 100,
                    food_cell_size: 20,
                    persistence_interval: 0,
                    chart_flush_interval: 0,
                    rng_seed: Some(0x1D38_7712),
                    ..ScriptBotsConfig::default()
                },
                5_000_u64,
            ),
            (
                "harsh metabolism",
                ScriptBotsConfig {
                    world_width: 120,
                    world_height: 120,
                    food_cell_size: 20,
                    metabolism_drain: 0.01,
                    movement_drain: 0.004,
                    persistence_interval: 0,
                    chart_flush_interval: 0,
                    rng_seed: Some(0x2E49_8A21),
                    ..ScriptBotsConfig::default()
                },
                500_u64,
            ),
            (
                "generous regrowth",
                ScriptBotsConfig {
                    world_width: 120,
                    world_height: 120,
                    food_cell_size: 20,
                    food_growth_rate: 0.06,
                    food_respawn_interval: 5,
                    persistence_interval: 0,
                    chart_flush_interval: 0,
                    rng_seed: Some(0x3F5A_9B32),
                    ..ScriptBotsConfig::default()
                },
                500_u64,
            ),
        ];
        for (label, config, ticks) in configs {
            let mut world = WorldState::new(config).expect("property world");
            for _ in 0..4 {
                world
                    .try_spawn_agent(AgentData::default())
                    .expect("property spawn");
            }
            let opening = world.resource_amounts();
            world.set_resource_ledger_enabled(true);
            for _ in 0..ticks {
                world.step().expect("property step");
            }
            let closing = world.resource_amounts();
            let observed = closing.delta_from(opening);
            let report = world.resource_ledger().clone();
            assert_eq!(report.completed_ticks, ticks, "{label}: every tick posted");
            let mut attributed = ResourceAmounts::default();
            for flow in &report.cumulative {
                attributed.add_assign(flow.delta);
            }
            let unexplained = observed.subtract(attributed);
            let gross = attributed.scale().max(observed.scale()).max(1.0);
            let tolerance = 1.0e-6 * gross;
            assert!(
                unexplained.within(tolerance),
                "{label}: {ticks} ticks must close the books: unexplained \
                 {unexplained:?} exceeds derived tolerance {tolerance} (gross {gross})"
            );
            // The class decomposition is the same sum regrouped — and it must
            // land on the OBSERVED stock change, which is what makes
            // "external_in - sinks + internal_net == delta(stock)" a property
            // of the run rather than a tautology about the report.
            let signed_total =
                |amounts: ResourceAmounts| amounts.food + amounts.energy + amounts.health;
            let mut by_class = [0.0_f64; 3];
            for flow in &report.cumulative {
                let lane = match RESOURCE_FLOW_KINDS[flow.kind.index()].flow_class() {
                    FlowClass::ExternalInput => 0,
                    FlowClass::Sink => 1,
                    FlowClass::InternalTransfer => 2,
                };
                by_class[lane] += signed_total(flow.delta);
            }
            let recomposed = by_class[0] + by_class[1] + by_class[2];
            let observed_scalar = signed_total(observed);
            assert!(
                (recomposed - observed_scalar).abs() <= tolerance,
                "{label}: external_in({}) - sinks({}) + internal_net({}) must equal \
                 delta(stocks) ({observed_scalar}) within {tolerance}",
                by_class[0],
                by_class[1],
                by_class[2]
            );
        }
    }

    /// Base scenario for the conservation-gate mutation suite (bd-16g.11.2):
    /// exercises grazing, regrowth, metabolism, reproduction, population
    /// injection, interventions, and giving in one world.
    fn mutation_suite_world(seed: u64) -> WorldState {
        mutation_suite_world_with_growth(seed, 0.04)
    }

    fn mutation_suite_world_with_growth(seed: u64, growth_rate: f32) -> WorldState {
        let mut world = WorldState::new(ScriptBotsConfig {
            world_width: 120,
            world_height: 120,
            food_cell_size: 20,
            initial_food: 0.2,
            food_max: 1.0,
            food_growth_rate: growth_rate,
            food_intake_rate: 0.4,
            food_transfer_rate: 0.4,
            food_respawn_interval: 7,
            food_respawn_amount: 0.2,
            metabolism_drain: 0.002,
            movement_drain: 0.001,
            temperature_discomfort_rate: 0.003,
            reproduction_energy_threshold: 0.8,
            reproduction_energy_cost: 0.8,
            reproduction_cooldown: 1,
            reproduction_attempt_interval: 1,
            reproduction_attempt_chance: 1.0,
            reproduction_child_energy: 0.4,
            closed: false,
            population_minimum: 8,
            population_spawn_interval: 5,
            aging_tick_interval: 1,
            aging_health_decay_rate: 0.005,
            aging_health_decay_max: 0.05,
            persistence_interval: 0,
            chart_flush_interval: 0,
            rng_seed: Some(seed),
            ..ScriptBotsConfig::default()
        })
        .expect("mutation suite world");
        for index in 0..6_u32 {
            let agent = world
                .try_spawn_agent(AgentData {
                    position: Position::new(40.0 + f32::from(index as u16) * 6.0, 60.0),
                    ..AgentData::default()
                })
                .expect("suite spawn");
            world
                .try_update_agent_runtime(agent, |runtime| {
                    runtime.energy = 1.5;
                    runtime.reproduction_counter = 10.0;
                })
                .expect("suite energy");
        }
        world
            .enqueue_intervention(Intervention::Bloom {
                region: Region::All,
                amount: 0.1,
            })
            .expect("suite bloom validates");
        world
    }

    fn run_gate(world: &mut WorldState, seed: u64, ticks: u64) -> economy::ConservationVerdict {
        world.set_resource_ledger_enabled(true);
        let mut gate = economy::ConservationGate::new();
        for _ in 0..ticks {
            world.step().expect("gate step");
            let latest = world.resource_ledger().latest.clone();
            if let Some(latest) = latest {
                gate.observe(&latest);
            }
        }
        economy::evaluate_conservation(&[gate.finish(seed)])
    }

    #[test]
    fn the_unmutated_gate_run_is_green() {
        // The alarm must stay quiet on a legal run: a gate that fires on a
        // legal-but-weird config gets muted, and a muted gate is a lie in a
        // green checkmark (bd-16g.11.2 anti-alarm-fatigue).
        let mut world = mutation_suite_world(0x6A7E_0001);
        let verdict = run_gate(&mut world, 0x6A7E_0001, 64);
        assert!(
            verdict.pass,
            "unmutated run must be green: {:?}",
            verdict.failures
        );
    }

    #[test]
    fn every_injectable_fault_turns_the_gate_red() {
        // The centerpiece of bd-16g.11.2: a conservation gate that has never
        // been observed to fail is not evidence of conservation. Every fault
        // must fail the gate — and within a documented bound, because a leak
        // that takes 40k ticks to detect would not have caught the historical
        // bugs in practice.
        for fault in LedgerFault::ALL {
            let seed = 0xFA07_0000 + fault as u64;
            let mut world = if matches!(fault, LedgerFault::MislabelSunlightAsTransfer) {
                mutation_suite_world_with_growth(seed, 0.5)
            } else {
                mutation_suite_world(seed)
            };
            // Give the fault's activity class its stage: aged agents for aging,
            // adjacent agents at full health for the health-gate fault.
            {
                let handles: Vec<AgentId> = world.agents().iter_handles().collect();
                if matches!(fault, LedgerFault::DropAgingPosting) {
                    let arena = world.agents.columns_mut();
                    for index in arena.ages_mut().iter_mut() {
                        *index = 12_500;
                    }
                }
                if matches!(
                    fault,
                    LedgerFault::CreditIntakeWithoutHealthGate
                        | LedgerFault::ForgetEnergyCapSpill
                        | LedgerFault::ForgetHealthCapSpill
                ) {
                    world.food_mut().cells_mut().fill(1.0);
                    if matches!(fault, LedgerFault::ForgetEnergyCapSpill) {
                        world.config.metabolism_drain = 0.0;
                        world.config.movement_drain = 0.0;
                        world.config.temperature_discomfort_rate = 0.0;
                        world.config.food_intake_rate = 1.0;
                    }
                    if matches!(
                        fault,
                        LedgerFault::CreditIntakeWithoutHealthGate
                            | LedgerFault::ForgetHealthCapSpill
                    ) {
                        let arena = world.agents.columns_mut();
                        for health in arena.health_mut().iter_mut() {
                            *health = 2.0;
                        }
                    }
                    for handle in world.agents().iter_handles().collect::<Vec<_>>() {
                        let _ = world.try_update_agent_runtime(handle, |runtime| {
                            runtime.energy = 1.99;
                            runtime.herbivore_tendency = 1.0;
                        });
                    }
                }
                if matches!(fault, LedgerFault::MislabelCarcassAsTransfer) {
                    if world.agents().len() >= 2 && world.runtime.values().all(|r| !r.spiked) {
                        let victim = world.agents().iter_handles().next();
                        if let Some(victim) = victim {
                            let idx = world.agents().index_of(victim);
                            if let Some(idx) = idx {
                                let arena = world.agents.columns_mut();
                                if let Some(health) = arena.health_mut().get_mut(idx) {
                                    *health = 0.0;
                                }
                                if let Some(age) = arena.ages_mut().get_mut(idx) {
                                    *age = 1000;
                                }
                            }
                            if let Some(runtime) = world.runtime.get_mut(victim) {
                                runtime.spiked = true;
                                runtime.combat.was_spiked_by_carnivore = true;
                            }
                            for (id, runtime) in world.runtime.iter_mut() {
                                if id != victim {
                                    runtime.herbivore_tendency = 0.0;
                                }
                            }
                        }
                    }
                }
                if matches!(fault, LedgerFault::SkipDeathResidue) {
                    let agent = world.agents().iter_handles().next();
                    if let Some(agent) = agent {
                        world.pending_deaths.push(agent);
                    }
                }
                let _ = handles;
            }
            world.inject_ledger_fault(fault);
            let verdict = run_gate(&mut world, seed, 64);
            assert!(
                !verdict.pass,
                "fault {fault:?} was not detected within 64 ticks"
            );
            let first_breach = verdict.seeds[0].breaches.first().or_else(|| {
                // Cumulative-only detections have no per-tick breach rows.
                None
            });
            if let Some(breach) = first_breach {
                assert!(
                    breach.tick.0 <= 64,
                    "fault {fault:?} detected too late (tick {})",
                    breach.tick.0
                );
            }
        }
    }

    #[test]
    fn stock_guard_fails_the_tick_a_mutation_has_no_posting() {
        // bd-16g.11.1 NEGATIVE (fault injection, proving the guard is not
        // decorative): mutate the food stock directly with NO matching posting —
        // the exact shape of the historical missing-`stage_actuation` bug — and
        // the debug StockGuard must fail on that very tick.
        let mut world = WorldState::new(ScriptBotsConfig {
            world_width: 200,
            world_height: 200,
            food_cell_size: 20,
            rng_seed: Some(0x570C_6661),
            ..ScriptBotsConfig::default()
        })
        .expect("world");
        world.set_resource_ledger_enabled(true);
        let opening = world.resource_amounts();
        world.resource_ledger.begin_tick(Tick(1), opening);
        // THE FAULT: food changes with no posting at all.
        world
            .try_update_food(|cells| {
                if let Some(cell) = cells.first_mut() {
                    *cell += 0.5;
                }
            })
            .expect("direct food mutation");
        let closing = world.resource_amounts();
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            world.resource_ledger.finish_tick(closing);
        }));
        assert!(
            outcome.is_err(),
            "StockGuard must fail the tick a mutation has no posting"
        );
    }

