    #[test]
    fn enabling_resource_ledger_does_not_change_characterization_digest() {
        let config = ScriptBotsConfig {
            world_width: 100,
            world_height: 100,
            food_cell_size: 10,
            initial_food: 0.4,
            food_respawn_interval: 0,
            population_minimum: 0,
            population_spawn_interval: 0,
            closed: true,
            persistence_interval: 0,
            rng_seed: Some(2_811),
            ..ScriptBotsConfig::default()
        };
        let mut uninstrumented = WorldState::new(config.clone()).expect("control world");
        let mut instrumented = WorldState::new(config).expect("instrumented world");
        instrumented.set_resource_ledger_enabled(true);
        let mut expected_cumulative: Vec<ResourceFlow> = RESOURCE_FLOW_KINDS
            .into_iter()
            .map(ResourceFlow::empty)
            .collect();

        for _ in 0..4 {
            uninstrumented.step().expect("control tick");
            instrumented.step().expect("instrumented tick");
            assert_latest_ledger_reconciles(&instrumented);
            for (expected, actual) in expected_cumulative.iter_mut().zip(
                &instrumented
                    .resource_ledger()
                    .latest
                    .as_ref()
                    .expect("instrumented tick report")
                    .flows,
            ) {
                expected.delta.add_assign(actual.delta);
                expected.activity.add_assign(actual.activity);
            }
            assert_eq!(
                uninstrumented
                    .characterization_digest_v0()
                    .expect("control digest"),
                instrumented
                    .characterization_digest_v0()
                    .expect("instrumented digest")
            );
        }
        assert_eq!(instrumented.resource_ledger().completed_ticks, 4);
        assert_eq!(
            instrumented.resource_ledger().cumulative,
            expected_cumulative
        );
        assert_eq!(uninstrumented.resource_ledger().completed_ticks, 0);
    }

    #[test]
    fn profiled_step_observes_the_authoritative_pipeline_without_changing_science() {
        let config = ScriptBotsConfig {
            world_width: 100,
            world_height: 100,
            food_cell_size: 10,
            population_minimum: 0,
            population_spawn_interval: 0,
            closed: true,
            persistence_interval: 0,
            rng_seed: Some(2_812),
            ..ScriptBotsConfig::default()
        };
        let mut control = WorldState::new(config.clone()).expect("control world");
        let mut profiled = WorldState::new(config).expect("profiled world");
        let mut step_profiler = WorldStepProfiler::default();
        let control_brain = control
            .brain_registry_mut()
            .expect("control profiler registry mutation")
            .register("profile-parity", |_rng| Ok(Box::new(StubBrain)));
        let profiled_brain = profiled
            .brain_registry_mut()
            .expect("profiled registry mutation")
            .register("profile-parity", |_rng| Ok(Box::new(StubBrain)));
        for ordinal in 0..2 {
            let control_agent = control.spawn_agent(sample_agent(ordinal));
            let profiled_agent = profiled.spawn_agent(sample_agent(ordinal));
            assert_eq!(control_agent, profiled_agent);
            assert!(
                control
                    .bind_agent_brain(control_agent, control_brain)
                    .expect("control brain")
            );
            assert!(
                profiled
                    .bind_agent_brain(profiled_agent, profiled_brain)
                    .expect("profiled brain")
            );
        }
        control.set_resource_ledger_enabled(true);
        profiled.set_resource_ledger_enabled(true);

        for expected_tick in 1..=3 {
            let control_events = control.step().expect("control tick");
            let profiled_events = profiled
                .step_profiled(&mut step_profiler)
                .expect("profiled tick");
            assert_eq!(control_events, profiled_events);

            let report = step_profiler.latest().expect("completed profile");
            assert_eq!(report.schema, WORLD_STEP_OUTCOME_PROFILE_SCHEMA);
            assert_eq!(report.tick, Tick(expected_tick));
            assert_eq!(report.stages().count(), WorldStepStage::COUNT);
            assert_eq!(report.elapsed_ns(WorldStepStage::Aging), None);
            assert!(
                WorldStepStage::all()
                    .iter()
                    .filter(|stage| **stage != WorldStepStage::Aging)
                    .all(|stage| report.elapsed_ns(*stage).is_some())
            );
            let stage_total = report
                .stages()
                .filter_map(|(_, elapsed_ns)| elapsed_ns)
                .sum::<u64>();
            assert!(report.total_ns >= stage_total);
            assert_eq!(
                control
                    .characterization_digest_v0()
                    .expect("control digest"),
                profiled
                    .characterization_digest_v0()
                    .expect("profiled digest")
            );
            assert_eq!(control.resource_ledger(), profiled.resource_ledger());
        }
    }

    /// Test double for [`ProfileTailClock`] that charges a fixed synthetic cost to each of the
    /// legacy v2 tail segments, so the boundary's accounting can be asserted exactly.
    ///
    /// This is injected through the same public `set_tail_clock` seam production uses, so it
    /// changes no struct layout and no statement sequence in the code under test (bd-dz37).
    #[derive(Debug, Default)]
    struct SyntheticTailClock {
        now_ns: u64,
        staging_advance_ns: u64,
        result_advance_ns: u64,
    }

    impl SyntheticTailClock {
        const fn new(staging_advance_ns: u64, result_advance_ns: u64) -> Self {
            Self {
                now_ns: 0,
                staging_advance_ns,
                result_advance_ns,
            }
        }
    }

    impl ProfileTailClock for SyntheticTailClock {
        fn synthetic_now_ns(&self) -> u64 {
            self.now_ns
        }

        fn advance_staging(&mut self) {
            self.now_ns = self.now_ns.saturating_add(self.staging_advance_ns);
        }

        fn advance_result(&mut self) {
            self.now_ns = self.now_ns.saturating_add(self.result_advance_ns);
        }
    }

    /// The shipped clock must contribute nothing, so an ordinary profiled step measures only the
    /// real monotonic clock. If this ever regressed, every production profile would carry
    /// fabricated time.
    #[test]
    fn the_shipped_tail_clock_contributes_no_synthetic_time() {
        let mut clock = SystemProfileTailClock;
        assert_eq!(clock.synthetic_now_ns(), 0);
        clock.advance_staging();
        clock.advance_result();
        assert_eq!(clock.synthetic_now_ns(), 0);

        let profiler = WorldStepProfiler::default();
        assert_eq!(
            profiler.synthetic_tail_ns(),
            0,
            "a default profiler must ship the zero-cost clock"
        );
    }

