    #[test]
    fn traced_step_keeps_retained_tail_identity_after_agent_death() {
        let (mut world, mut session) =
            world_with_session(quiet_trace_config(2_820, 3), NullPersistence);
        let agent = world.spawn_agent(sample_agent(0));
        let agent_uid = world.agent_uid(agent).expect("retained-tail stable uid");
        session
            .step(&mut world)
            .expect("non-cadence retained-tail tick");
        assert_eq!(
            world
                .pending_persistence_runtime_tail
                .get(agent)
                .expect("retained runtime tail")
                .agent_uid,
            agent_uid
        );
        let index = world
            .agents
            .index_of(agent)
            .expect("retained-tail agent index");
        world.agents.columns_mut().health_mut()[index] = 0.0;

        let mut tracer = WorldStepTracer::default();
        session
            .step_traced(&mut world, &mut tracer)
            .expect("death with retained tail remains traceable");
        assert!(world.agent_uid(agent).is_none());
        assert!(
            tracer
                .latest()
                .expect("retained-tail trace")
                .stages
                .iter()
                .all(|stage| stage.capture.is_ok())
        );
        assert!(world.pending_persistence_runtime_tail.is_empty());
    }

    #[test]
    fn world_digest_v1_covers_declared_factory_state_and_names_opaque_factories() {
        fn registry_world(factory_digest: u64) -> WorldState {
            let mut world =
                WorldState::new(quiet_trace_config(2_821, 0)).expect("factory digest world");
            world
                .brain_registry_mut()
                .expect("factory digest registry")
                .register_with_state_digest("factory-family", factory_digest, |_rng| {
                    Ok(Box::new(StubBrain))
                });
            world
        }

        let left = registry_world(11)
            .world_digest_v1()
            .expect("left factory digest");
        let right = registry_world(12)
            .world_digest_v1()
            .expect("right factory digest");
        assert_ne!(left.brain_registry, right.brain_registry);
        assert_ne!(left.overall, right.overall);
        assert!(left.factory_state_covered);
        assert!(left.uncovered_factory_families.is_empty());

        let mut opaque =
            WorldState::new(quiet_trace_config(2_821, 0)).expect("opaque factory world");
        opaque
            .brain_registry_mut()
            .expect("opaque factory registry")
            .register("opaque-family", |_rng| Ok(Box::new(StubBrain)));
        let opaque = opaque
            .world_digest_v1()
            .expect("opaque factory digest remains honest");
        assert!(!opaque.factory_state_covered);
        assert_eq!(
            opaque.uncovered_factory_families,
            vec!["opaque-family".to_owned()]
        );
    }

    #[test]
    fn uid_canonical_tick_matches_across_slot_and_dense_layouts() {
        fn layout_world() -> WorldState {
            let config = ScriptBotsConfig {
                spike_radius: 20.0,
                spike_damage: 0.5,
                spike_energy_cost: 0.02,
                spike_min_length: 0.1,
                spike_alignment_cosine: 0.1,
                spike_speed_damage_bonus: 0.0,
                spike_length_damage_bonus: 0.0,
                carcass_distribution_radius: 30.0,
                carcass_health_reward: 0.4,
                carcass_reproduction_reward: 0.2,
                carcass_neighbor_exponent: 1.0,
                carcass_maturity_age: 1,
                carcass_energy_share_rate: 0.5,
                ..quiet_trace_config(2_823, 0)
            };
            let mut world = WorldState::new(config).expect("UID-canonical layout world");
            let attacker = world.spawn_agent(sample_agent(0));
            let first_victim = world.spawn_agent(sample_agent(1));
            let second_victim = world.spawn_agent(sample_agent(2));
            let survivor = world.spawn_agent(sample_agent(3));
            let attacker_brain = world
                .brain_registry_mut()
                .expect("layout aggressor registry")
                .register_with_state_digest(
                    "test.uid-layout-aggressor",
                    0x5549_444c_4159_4f41,
                    |_rng| Ok(Box::new(LedgerAggressorBrain)),
                );
            let idle_brain = world
                .brain_registry_mut()
                .expect("layout idle registry")
                .register_with_state_digest(
                    "test.uid-layout-idle",
                    0x5549_444c_4159_4f49,
                    |_rng| Ok(Box::new(LedgerIdleBrain)),
                );
            assert!(world.bind_agent_brain(attacker, attacker_brain).unwrap());
            assert!(world.bind_agent_brain(first_victim, idle_brain).unwrap());
            assert!(world.bind_agent_brain(second_victim, idle_brain).unwrap());

            let attacker_idx = world.agents.index_of(attacker).unwrap();
            let first_victim_idx = world.agents.index_of(first_victim).unwrap();
            let second_victim_idx = world.agents.index_of(second_victim).unwrap();
            let survivor_idx = world.agents.index_of(survivor).unwrap();
            let columns = world.agents.columns_mut();
            columns.positions_mut()[attacker_idx] = Position::new(10.0, 10.0);
            columns.positions_mut()[first_victim_idx] = Position::new(15.0, 10.0);
            columns.positions_mut()[second_victim_idx] = Position::new(16.0, 10.0);
            columns.positions_mut()[survivor_idx] = Position::new(18.0, 10.0);
            columns.headings_mut()[attacker_idx] = 0.0;
            columns.headings_mut()[first_victim_idx] = 0.0;
            columns.headings_mut()[second_victim_idx] = 0.0;
            columns.headings_mut()[survivor_idx] = 0.0;
            columns.health_mut()[attacker_idx] = 1.0;
            columns.health_mut()[first_victim_idx] = 0.08;
            columns.health_mut()[second_victim_idx] = 0.08;
            columns.health_mut()[survivor_idx] = 1.0;
            columns.ages_mut()[attacker_idx] = 5;
            columns.ages_mut()[first_victim_idx] = 5;
            columns.ages_mut()[second_victim_idx] = 5;
            columns.ages_mut()[survivor_idx] = 5;
            columns.spike_lengths_mut()[attacker_idx] = 1.0;

            let attacker_runtime = world.agent_runtime_mut(attacker).unwrap();
            attacker_runtime.energy = 1.0;
            attacker_runtime.herbivore_tendency = 0.0;
            let first_victim_runtime = world.agent_runtime_mut(first_victim).unwrap();
            first_victim_runtime.energy = 0.2;
            first_victim_runtime.herbivore_tendency = 1.0;
            let second_victim_runtime = world.agent_runtime_mut(second_victim).unwrap();
            second_victim_runtime.energy = 0.3;
            second_victim_runtime.herbivore_tendency = 1.0;
            let survivor_runtime = world.agent_runtime_mut(survivor).unwrap();
            survivor_runtime.energy = 0.5;
            survivor_runtime.herbivore_tendency = 0.0;
            world.set_resource_ledger_enabled(true);
            world
        }

        let mut left = layout_world();
        let mut right = layout_world();
        let handles: Vec<_> = right.agents.iter_handles().collect();
        permute_agent_associations(&mut right, &handles, &[2, 0, 3, 1]);

        assert_ne!(uid_slot_signature(&left), uid_slot_signature(&right));
        assert_ne!(
            left.agents
                .iter_handles()
                .map(|id| left.agent_uid(id).unwrap())
                .collect::<Vec<_>>(),
            right
                .agents
                .iter_handles()
                .map(|id| right.agent_uid(id).unwrap())
                .collect::<Vec<_>>()
        );
        assert_ne!(
            left.characterization_digest_v0()
                .expect("left legacy layout digest"),
            right
                .characterization_digest_v0()
                .expect("right legacy layout digest"),
            "legacy raw-slot characterization must prove the fixture layouts really differ"
        );
        assert_eq!(
            left.world_digest_v1().expect("left pre-step V1.6"),
            right.world_digest_v1().expect("right pre-step V1.6")
        );

        let mut left_tracer = WorldStepTracer::default();
        let mut right_tracer = WorldStepTracer::default();
        let left_completion = left
            .step_traced_outcome(&mut left_tracer)
            .expect("left canonical transition");
        let right_completion = right
            .step_traced_outcome(&mut right_tracer)
            .expect("right canonical transition");
        assert!(left_completion.fault.is_none());
        assert!(right_completion.fault.is_none());
        assert_eq!(
            left_completion.outcome.events,
            right_completion.outcome.events
        );
        assert_eq!(
            left_completion.outcome.summary,
            right_completion.outcome.summary
        );
        assert_eq!(
            left_completion.outcome.births,
            right_completion.outcome.births
        );
        assert_eq!(
            left_completion.outcome.deaths,
            right_completion.outcome.deaths
        );
        assert_eq!(
            left_completion.outcome.combat,
            right_completion.outcome.combat
        );
        assert_eq!(
            left_completion.outcome.resource_tick,
            right_completion.outcome.resource_tick
        );
        assert_eq!(
            left_completion.outcome.persistence.status(),
            right_completion.outcome.persistence.status()
        );
        assert!(left_completion.outcome.combat.spike_hits > 0);
        assert!(left_completion.outcome.deaths.len() >= 2);
        assert!(
            left_completion
                .outcome
                .deaths
                .windows(2)
                .all(|pair| pair[0].agent_uid < pair[1].agent_uid),
            "death records must commit in stable UID order"
        );
        assert!(left_completion.outcome.resource_tick.is_some());
        let left_trace = left_tracer.latest().expect("left canonical trace");
        let right_trace = right_tracer.latest().expect("right canonical trace");
        assert!(
            left_tracer
                .death_cleanup_input_pending_deaths()
                .unwrap_or(0)
                > 0
        );
        assert_eq!(
            left_tracer.death_cleanup_input_pending_deaths(),
            right_tracer.death_cleanup_input_pending_deaths()
        );
        assert!(left_trace.stages.iter().all(|stage| stage.capture.is_ok()));
        left_trace
            .validate_contract()
            .expect("left canonical trace contract");
        right_trace
            .validate_contract()
            .expect("right canonical trace contract");
        assert_eq!(left_trace, right_trace);
        assert_eq!(left_trace.first_divergence(right_trace).unwrap(), None);
        assert_eq!(left.resource_ledger(), right.resource_ledger());
        assert_eq!(left.history, right.history);
        assert_eq!(
            left.world_digest_v1().expect("left final V1.6"),
            right.world_digest_v1().expect("right final V1.6")
        );
    }

    #[test]
    fn uid_canonical_reproduction_assigns_identical_child_genomes_and_uids() {
        fn reproduction_world() -> WorldState {
            let (mut world, key) = protocol_fixture_world(
                "test-uid-layout-protocol",
                OffspringStatePolicy::Reset,
                1.0,
            );
            let parents = [
                protocol_fixture_parent(&mut world, key, 11),
                protocol_fixture_parent(&mut world, key, 22),
                protocol_fixture_parent(&mut world, key, 33),
            ];
            for (index, parent) in parents.into_iter().enumerate() {
                replace_fixture_material(
                    &mut world,
                    key,
                    parent,
                    "test-uid-layout-protocol",
                    index as i8 + 1,
                    -(index as i8),
                );
                let dense = world.agents.index_of(parent).unwrap();
                world.agents.columns_mut().ages_mut()[dense] = 5;
                let runtime = world.agent_runtime_mut(parent).unwrap();
                runtime.energy = if index == 1 { 0.0 } else { 5.0 };
                runtime.reproduction_counter = if index == 1 { 0.0 } else { f32::MAX };
                runtime.mutation_rates = MutationRates {
                    primary: 1.0,
                    secondary: 1.0,
                };
            }
            world.set_resource_ledger_enabled(true);
            world
        }

        let mut left = reproduction_world();
        let mut right = reproduction_world();
        let handles: Vec<_> = right.agents.iter_handles().collect();
        permute_agent_associations(&mut right, &handles, &[2, 0, 1]);
        assert_ne!(uid_slot_signature(&left), uid_slot_signature(&right));
        assert_eq!(
            left.world_digest_v1().expect("left reproduction input"),
            right.world_digest_v1().expect("right reproduction input")
        );

        let mut left_tracer = WorldStepTracer::default();
        let mut right_tracer = WorldStepTracer::default();
        let left_completion = left
            .step_traced_outcome(&mut left_tracer)
            .expect("left protocol reproduction");
        let right_completion = right
            .step_traced_outcome(&mut right_tracer)
            .expect("right protocol reproduction");
        assert!(left_completion.fault.is_none());
        assert!(right_completion.fault.is_none());
        assert_eq!(
            left_completion.outcome.events,
            right_completion.outcome.events
        );
        assert_eq!(
            left_completion.outcome.summary,
            right_completion.outcome.summary
        );
        assert_eq!(
            left_completion.outcome.births,
            right_completion.outcome.births
        );
        assert_eq!(
            left_completion.outcome.deaths,
            right_completion.outcome.deaths
        );
        assert_eq!(
            left_completion.outcome.combat,
            right_completion.outcome.combat
        );
        assert_eq!(
            left_completion.outcome.resource_tick,
            right_completion.outcome.resource_tick
        );
        assert_eq!(left_completion.outcome.births.len(), 2);
        assert_eq!(
            left_completion
                .outcome
                .births
                .iter()
                .map(|record| record.parent_a)
                .collect::<Vec<_>>(),
            vec![Some(AgentUid(1)), Some(AgentUid(3))]
        );
        assert!(left_tracer.population_input_pending_spawns().unwrap_or(0) > 0);
        assert_eq!(
            left_tracer.population_input_pending_spawns(),
            right_tracer.population_input_pending_spawns()
        );
        let left_trace = left_tracer.latest().expect("left reproduction trace");
        let right_trace = right_tracer.latest().expect("right reproduction trace");
        assert!(left_trace.stages.iter().all(|stage| stage.capture.is_ok()));
        left_trace
            .validate_contract()
            .expect("left reproduction trace contract");
        right_trace
            .validate_contract()
            .expect("right reproduction trace contract");
        assert_eq!(left_trace, right_trace);
        assert_eq!(left_trace.first_divergence(right_trace).unwrap(), None);
        assert_eq!(left.resource_ledger(), right.resource_ledger());

        for birth in &left_completion.outcome.births {
            let left_child = agent_id_for_uid(&left, birth.agent_uid);
            let right_child = agent_id_for_uid(&right, birth.agent_uid);
            assert_eq!(
                left.agent_runtime(left_child).unwrap().lineage,
                [birth.parent_a, birth.parent_b]
            );
            assert_eq!(
                right.agent_runtime(right_child).unwrap().lineage,
                [birth.parent_a, birth.parent_b]
            );
            assert_eq!(
                left.agent_brain_genome(left_child),
                right.agent_brain_genome(right_child)
            );
            let genome = left
                .agent_brain_genome(left_child)
                .expect("reproduction child genome");
            assert_eq!(
                genome.provenance().parents,
                [birth.parent_a, birth.parent_b]
            );
            assert!(matches!(
                genome.provenance().derivation,
                BrainGenomeDerivation::Crossover | BrainGenomeDerivation::CrossoverThenMutation
            ));
            let expected_hashes = [birth.parent_a, birth.parent_b].map(|uid| {
                uid.map(|uid| {
                    let parent = agent_id_for_uid(&left, uid);
                    left.agent_brain_genome(parent)
                        .expect("reproduction parent genome")
                        .material_hash()
                })
            });
            assert_eq!(genome.provenance().parent_genome_hashes, expected_hashes);
            assert_eq!(
                left.agent_brain_evaluator_state(left_child).unwrap(),
                right.agent_brain_evaluator_state(right_child).unwrap()
            );
        }
        let left_final = left.world_digest_v1().expect("left reproduction V1.6");
        let right_final = right.world_digest_v1().expect("right reproduction V1.6");
        assert_eq!(left_final.rng, right_final.rng);
        assert_eq!(left_final.counters, right_final.counters);
        assert_eq!(left_final, right_final);
    }

    #[test]
    fn uid_canonical_population_crossover_preserves_directional_protocol_parents() {
        fn crossover_world() -> WorldState {
            let mut config = protocol_reproduction_config(0.0);
            config.closed = false;
            config.population_spawn_interval = 1;
            config.population_spawn_count = 1;
            config.population_crossover_chance = 1.0;
            config.reproduction_energy_threshold = 0.0;
            config.reproduction_attempt_chance = 0.0;
            let mut world = WorldState::new(config).expect("scheduled crossover world");
            let family_id = "test-uid-layout-scheduled-protocol";
            let key = world
                .register_brain_family(
                    family_id,
                    Box::new(FixtureBrainFamily::with_policy(
                        family_id,
                        OffspringStatePolicy::Reset,
                    )),
                )
                .expect("register scheduled protocol family");
            let parents = [
                protocol_fixture_parent(&mut world, key, 44),
                protocol_fixture_parent(&mut world, key, 55),
                protocol_fixture_parent(&mut world, key, 66),
            ];
            for (index, parent) in parents.into_iter().enumerate() {
                replace_fixture_material(
                    &mut world,
                    key,
                    parent,
                    family_id,
                    index as i8 + 4,
                    index as i8 - 1,
                );
                let dense = world.agents.index_of(parent).unwrap();
                world.agents.columns_mut().ages_mut()[dense] = (index as u32 + 1) * 3;
                world.agent_runtime_mut(parent).unwrap().mutation_rates = MutationRates {
                    primary: 1.0,
                    secondary: 1.0,
                };
            }
            world.set_resource_ledger_enabled(true);
            world
        }

        let mut left = crossover_world();
        let mut right = crossover_world();
        let handles: Vec<_> = right.agents.iter_handles().collect();
        permute_agent_associations(&mut right, &handles, &[2, 0, 1]);
        assert_ne!(uid_slot_signature(&left), uid_slot_signature(&right));
        assert_eq!(
            left.world_digest_v1().expect("left crossover input"),
            right.world_digest_v1().expect("right crossover input")
        );

        let mut left_tracer = WorldStepTracer::default();
        let mut right_tracer = WorldStepTracer::default();
        let left_completion = left
            .step_traced_outcome(&mut left_tracer)
            .expect("left scheduled crossover");
        let right_completion = right
            .step_traced_outcome(&mut right_tracer)
            .expect("right scheduled crossover");
        assert!(left_completion.fault.is_none());
        assert!(right_completion.fault.is_none());
        assert_eq!(
            left_completion.outcome.events,
            right_completion.outcome.events
        );
        assert_eq!(
            left_completion.outcome.summary,
            right_completion.outcome.summary
        );
        assert_eq!(
            left_completion.outcome.births,
            right_completion.outcome.births
        );
        assert_eq!(
            left_completion.outcome.resource_tick,
            right_completion.outcome.resource_tick
        );
        assert_eq!(left_completion.outcome.births.len(), 1);
        let birth = &left_completion.outcome.births[0];
        assert_eq!(birth.origin, BirthOrigin::Injected);
        assert!(birth.parent_a.is_some());
        assert!(birth.parent_b.is_some());
        assert_ne!(birth.parent_a, birth.parent_b);

        let left_child = agent_id_for_uid(&left, birth.agent_uid);
        let right_child = agent_id_for_uid(&right, birth.agent_uid);
        let left_genome = left
            .agent_brain_genome(left_child)
            .expect("left scheduled child genome");
        let right_genome = right
            .agent_brain_genome(right_child)
            .expect("right scheduled child genome");
        assert_eq!(
            left.agent_runtime(left_child).unwrap().lineage,
            [birth.parent_a, birth.parent_b]
        );
        assert_eq!(
            right.agent_runtime(right_child).unwrap().lineage,
            [birth.parent_a, birth.parent_b]
        );
        assert_eq!(left_genome, right_genome);
        assert_eq!(
            left_genome.provenance().parents,
            [birth.parent_a, birth.parent_b]
        );
        assert!(matches!(
            left_genome.provenance().derivation,
            BrainGenomeDerivation::Crossover | BrainGenomeDerivation::CrossoverThenMutation
        ));
        let expected_hashes = [birth.parent_a, birth.parent_b].map(|uid| {
            uid.map(|uid| {
                let parent = agent_id_for_uid(&left, uid);
                left.agent_brain_genome(parent)
                    .expect("scheduled parent genome")
                    .material_hash()
            })
        });
        assert_eq!(
            left_genome.provenance().parent_genome_hashes,
            expected_hashes
        );
        assert_eq!(
            left.agent_brain_evaluator_state(left_child).unwrap(),
            right.agent_brain_evaluator_state(right_child).unwrap()
        );

        let left_trace = left_tracer.latest().expect("left scheduled trace");
        let right_trace = right_tracer.latest().expect("right scheduled trace");
        assert!(left_trace.stages.iter().all(|stage| stage.capture.is_ok()));
        left_trace
            .validate_contract()
            .expect("left scheduled trace contract");
        right_trace
            .validate_contract()
            .expect("right scheduled trace contract");
        assert_eq!(left_trace.first_divergence(right_trace).unwrap(), None);
        assert_eq!(left.resource_ledger(), right.resource_ledger());
        let left_final = left.world_digest_v1().expect("left crossover V1.6");
        let right_final = right.world_digest_v1().expect("right crossover V1.6");
        assert_eq!(left_final.rng, right_final.rng);
        assert_eq!(left_final.counters, right_final.counters);
        assert_eq!(left_final, right_final);
    }

    #[test]
    // bd-tqpj: the `.count` suffix filter matches a metric-name convention, not a
    // filesystem extension — the case-sensitive comparison is intentional.
    #[allow(clippy::case_sensitive_file_extension_comparisons)]
    // bd-tqpj: the spy-log mutex guard must stay held across this test's batch assertions; drop order is semantic.
    #[allow(clippy::significant_drop_tightening)]
    fn persistence_batch_orders_agents_and_brain_metrics_stably() {
        let config = ScriptBotsConfig {
            spike_damage: 0.0,
            spike_energy_cost: 0.0,
            ..quiet_trace_config(2_822, 1)
        };
        let spy = SpyPersistence::default();
        let logs = Arc::clone(&spy.logs);
        let (mut world, mut session) = world_with_session(config, spy);
        let first = world.spawn_agent(sample_agent(0));
        let second = world.spawn_agent(sample_agent(1));
        let third = world.spawn_agent(sample_agent(2));
        let aggressor = world
            .brain_registry_mut()
            .expect("ordered batch aggressor registry")
            .register("test.resource-ledger-aggressor", |_rng| {
                Ok(Box::new(LedgerAggressorBrain))
            });
        let idle = world
            .brain_registry_mut()
            .expect("ordered batch idle registry")
            .register("test.resource-ledger-idle", |_rng| {
                Ok(Box::new(LedgerIdleBrain))
            });
        assert!(
            world
                .bind_agent_brain(second, aggressor)
                .expect("ordered batch aggressor binding")
        );
        assert!(
            world
                .bind_agent_brain(third, idle)
                .expect("ordered batch idle binding")
        );
        assert!(world.remove_agent(first).is_some());

        session
            .step(&mut world)
            .expect("ordered persistence batch tick");
        let entries = logs.lock().expect("ordered batch logs");
        let batch = entries.last().expect("ordered persistence batch");
        let agent_uids: Vec<_> = batch
            .agents
            .iter()
            .map(|agent| agent.identity.uid)
            .collect();
        let mut sorted_agent_uids = agent_uids.clone();
        sorted_agent_uids.sort_unstable();
        assert_eq!(agent_uids, sorted_agent_uids);

        let brain_count_metrics: Vec<_> = batch
            .metrics
            .iter()
            .map(|metric| metric.name.as_ref())
            .filter(|name| name.starts_with("brain.population.") && name.ends_with(".count"))
            .collect();
        let mut sorted_brain_count_metrics = brain_count_metrics.clone();
        sorted_brain_count_metrics.sort_unstable();
        assert_eq!(brain_count_metrics, sorted_brain_count_metrics);
        assert_eq!(brain_count_metrics.len(), 2);
    }

    #[test]
    fn world_digest_v1_counters_lane_covers_every_agent_continuation() {
        let mut world = WorldState::new(ScriptBotsConfig {
            population_minimum: 0,
            population_spawn_interval: 0,
            closed: true,
            rng_seed: Some(0xC0A7_EA55),
            ..ScriptBotsConfig::default()
        })
        .expect("counter-digest world");
        let agent = world.spawn_agent(sample_agent(0));
        let baseline = world.world_digest_v1().expect("baseline counter digest");

        for counters in [
            AgentRngCountersV1::from_ordinals(1, 0, 0),
            AgentRngCountersV1::from_ordinals(0, 1, 0),
            AgentRngCountersV1::from_ordinals(0, 0, 1),
        ] {
            assert!(world.agent_rng_counters.insert(agent, counters).is_some());
            let changed = world
                .world_digest_v1()
                .expect("counter-mutated world digest");
            assert_ne!(changed.counters, baseline.counters);
            assert_ne!(changed.overall, baseline.overall);

            let mut normalized = changed;
            normalized.counters.clone_from(&baseline.counters);
            normalized.overall.clone_from(&baseline.overall);
            assert_eq!(
                normalized, baseline,
                "an agent continuation must move only the counters lane and aggregate"
            );

            assert!(
                world
                    .agent_rng_counters
                    .insert(agent, AgentRngCountersV1::default())
                    .is_some()
            );
            assert_eq!(
                world.world_digest_v1().expect("restored counter digest"),
                baseline
            );
        }

        assert!(world.agent_rng_counters.remove(agent).is_some());
        assert!(matches!(
            world.world_digest_v1(),
            Err(CharacterizationError::MissingAgentRngCounters { .. })
        ));
        assert!(matches!(
            world.ordered_agent_rng_counters_v1(),
            Err(CharacterizationError::MissingAgentRngCounters { .. })
        ));
    }

    #[test]
    fn world_digest_v1_covers_config_effects_and_derived_transition_state() {
        let (mut world, _, _) = {
            let mut world = WorldState::new(ScriptBotsConfig {
                world_width: 100,
                world_height: 100,
                food_cell_size: 10,
                population_minimum: 0,
                population_spawn_interval: 0,
                closed: true,
                rng_seed: Some(2_817),
                ..ScriptBotsConfig::default()
            })
            .expect("V1 lane world");
            let first = world.spawn_agent(sample_agent(0));
            let second = world.spawn_agent(sample_agent(1));
            (world, first, second)
        };

        let before_config = world.world_digest_v1().expect("config baseline V1");
        world.config.closed = false;
        let after_config = world.world_digest_v1().expect("config-mutated V1");
        assert_ne!(before_config.config, after_config.config);
        assert_ne!(before_config.overall, after_config.overall);
        assert_eq!(before_config.effects, after_config.effects);
        assert_eq!(
            before_config.derived_transition,
            after_config.derived_transition
        );

        let before_effect = after_config;
        world.active_effects.push(ActiveEffect {
            region: Region::All,
            ticks_remaining: 2,
            kind: ActiveEffectKind::GrowthScale(1.0),
        });
        let after_effect = world.world_digest_v1().expect("effect-mutated V1");
        assert_eq!(before_effect.config, after_effect.config);
        assert_ne!(before_effect.effects, after_effect.effects);
        assert_eq!(
            before_effect.derived_transition,
            after_effect.derived_transition
        );
        assert_ne!(before_effect.overall, after_effect.overall);

        let before_derived = after_effect;
        world.food_profiles[0].nutrient_density += 0.125;
        let after_derived = world.world_digest_v1().expect("derived-mutated V1");
        assert_eq!(before_derived.config, after_derived.config);
        assert_eq!(before_derived.effects, after_derived.effects);
        assert_ne!(
            before_derived.derived_transition,
            after_derived.derived_transition
        );
        assert_ne!(before_derived.overall, after_derived.overall);

        let before_operational = after_derived;
        world.config.initial_food = 0.375;
        world.config.rng_seed = Some(99);
        world.config.chart_flush_interval = 7;
        world.config.history_capacity = 3;
        world.config.narrative_interval = 2;
        world.config.narrative_capacity = 4;
        world.config.persistence_interval = 9;
        world.config.analytics_stride = AnalyticsStride {
            macro_metrics: 8,
            behavior_metrics: 7,
            lifecycle_events: 6,
        };
        world.config.neuroflow.enabled = !world.config.neuroflow.enabled;
        world.config.control.auto_pause_on_spike_hit = true;
        world.config.render.tonemap_exposure_bias = Some(1.25);
        let after_operational = world
            .world_digest_v1()
            .expect("operational-policy-mutated V1");
        assert_eq!(before_operational.config, after_operational.config);
        assert_eq!(before_operational.overall, after_operational.overall);
    }

    #[test]
    fn profiled_step_preserves_persistence_failure_and_latched_boundary() {
        let config = ScriptBotsConfig {
            persistence_interval: 1,
            population_minimum: 0,
            population_spawn_interval: 0,
            closed: true,
            rng_seed: Some(2_813),
            ..ScriptBotsConfig::default()
        };
        let control_logs = Arc::new(Mutex::new(Vec::new()));
        let profiled_logs = Arc::new(Mutex::new(Vec::new()));
        let (mut control, mut control_session) = world_with_session(
            config.clone(),
            RejectOncePersistence {
                logs: Arc::clone(&control_logs),
                reject_next: true,
            },
        );
        let (mut profiled, mut profiled_session) = world_with_session(
            config,
            RejectOncePersistence {
                logs: Arc::clone(&profiled_logs),
                reject_next: true,
            },
        );
        let mut step_profiler = WorldStepProfiler::default();

        let control_error = control_session
            .step(&mut control)
            .expect_err("control persistence rejection");
        let profiled_error = profiled_session
            .step_profiled(&mut profiled, &mut step_profiler)
            .expect_err("profiled persistence rejection");
        assert!(
            matches!(
                (&control_error, &profiled_error),
                (
                    WorldStepError::Persistence(_),
                    WorldStepError::Persistence(_)
                )
            ),
            "expected matching typed persistence errors, got {control_error:?} and {profiled_error:?}"
        );
        let (
            WorldStepError::Persistence(control_persistence),
            WorldStepError::Persistence(profiled_persistence),
        ) = (&control_error, &profiled_error)
        else {
            return;
        };
        assert_eq!(control_persistence, profiled_persistence);
        assert_eq!(control.tick(), Tick(1));
        assert_eq!(profiled.tick(), Tick(1));
        assert!(matches!(
            profiled.world_digest_v1(),
            Err(CharacterizationError::NonContinuable {
                blocker: WorldContinuationBlocker::RetainedPersistenceBatch
            })
        ));
        assert!(control_session.fault().is_some());
        assert!(profiled_session.fault().is_some());
        assert_persistence_batches_exact(
            control_session
                .pending_batch()
                .expect("control rejected batch remains staged"),
            profiled_session
                .pending_batch()
                .expect("profiled rejected batch remains staged"),
        );
        assert_eq!(
            control.persistence_boundary,
            PersistenceBoundaryStatus::Pending { tick: Tick(1) }
        );
        assert_eq!(control.persistence_boundary, profiled.persistence_boundary);
        let profiled_retained = Arc::clone(
            &profiled_session
                .pending
                .as_ref()
                .expect("profiled rejected batch remains staged")
                .batch,
        );
        assert_eq!(
            step_profiler.latest().expect("failed tick profile").tick,
            Tick(1)
        );
        assert_eq!(
            format!("{:?}", *control_logs.lock().unwrap()),
            format!("{:?}", *profiled_logs.lock().unwrap())
        );
        assert_eq!(
            control
                .characterization_digest_v0()
                .expect("control failure digest"),
            profiled
                .characterization_digest_v0()
                .expect("profiled failure digest")
        );

        let digest = profiled
            .characterization_digest_v0()
            .expect("latched digest");
        let repeated = profiled_session
            .step_profiled(&mut profiled, &mut step_profiler)
            .expect_err("latched failure blocks a second tick");
        assert_eq!(repeated.to_string(), profiled_error.to_string());
        assert_same_staged_batch(&profiled_session, &profiled_retained);
        assert_eq!(profiled.tick(), Tick(1));
        assert_eq!(
            profiled
                .characterization_digest_v0()
                .expect("repeated latched digest"),
            digest
        );
    }

    #[test]
    fn dynamic_snapshot_uses_live_aggregates_after_post_tick_mutation() {
        let config = ScriptBotsConfig {
            population_minimum: 0,
            population_spawn_interval: 0,
            persistence_interval: 0,
            closed: true,
            rng_seed: Some(2_814),
            ..ScriptBotsConfig::default()
        };
        let mut world = WorldState::new(config).expect("snapshot world");
        let first_id = world.spawn_agent(sample_agent(0));
        world.step().expect("completed tick");
        let second_id = world.spawn_agent(sample_agent(1));

        let snapshot = DynamicWorldSnapshot::from_world(&world);
        let total_energy = snapshot
            .agents
            .iter()
            .map(|agent| agent.energy)
            .sum::<f32>();
        let total_health = snapshot
            .agents
            .iter()
            .map(|agent| agent.health)
            .sum::<f32>();
        assert_eq!(snapshot.tick, world.tick().0);
        assert_eq!(snapshot.summary.agent_count, world.agent_count());
        assert_eq!(snapshot.summary.agent_count, snapshot.agents.len());
        assert_eq!(snapshot.summary.total_energy, total_energy);
        assert_eq!(
            snapshot.summary.average_energy,
            total_energy / snapshot.agents.len() as f32
        );
        assert_eq!(
            snapshot.summary.average_health,
            total_health / snapshot.agents.len() as f32
        );

        for id in [first_id, second_id] {
            let dense_index = world.agents().index_of(id).expect("live dense index");
            let scalar = world.agents().columns().snapshot(dense_index);
            let runtime = world.agent_runtime(id).expect("live runtime");
            let projected = snapshot
                .agents
                .iter()
                .find(|agent| agent.id == id.raw())
                .expect("projected live agent");
            assert_eq!(projected.uid, world.agent_uid(id).expect("live uid"));
            assert_eq!(projected.age, scalar.age);
            assert_eq!(projected.generation, scalar.generation);
            assert_eq!(projected.herbivore_tendency, runtime.herbivore_tendency);
            assert_eq!(projected.brain_key, runtime.brain.registry_key());
        }

        let first_stable_uid = world.agent_uid(first_id).expect("first uid before removal");
        world
            .remove_agent(first_id)
            .expect("remove first snapshot agent");
        let replacement_id = world.spawn_agent(sample_agent(2));
        let replacement_stable_uid = world
            .agent_uid(replacement_id)
            .expect("replacement stable uid");
        let churned = DynamicWorldSnapshot::from_world(&world);
        assert_ne!(replacement_stable_uid, first_stable_uid);
        assert!(
            churned
                .agents
                .iter()
                .all(|agent| agent.uid != first_stable_uid)
        );
        assert!(churned.agents.iter().any(|agent| {
            agent.id == replacement_id.raw() && agent.uid == replacement_stable_uid
        }));
    }

